// Original lessons and examples. OpenStax links are further-reading references.
// Engineering situations are teaching models, not design specifications.
const books = {p:'prealgebra-2e',e:'elementary-algebra-2e',i:'intermediate-algebra-2e',c:'precalculus-2e'};
const S = (book,slug,title) => ({title:'OpenStax: '+title,url:`https://openstax.org/books/${books[book]}/pages/${slug}`});
const W = (title,given,steps,answer,check) => ({title,given,steps,answer,check});
const Q = (prompt,options,answer,explanation) => ({prompt,options:options.map((text,i)=>({id:'abcd'[i],text})),answer,explanation});

const arithmetic = [
{id:'place-value',stage:'arithmetic',order:1,title:'Numbers, place value, and estimation',subtitle:'A digit gets its value from where it stands.',prerequisites:[],
why:'Reading quantities accurately comes before calculating with them. Place value explains written arithmetic, decimal notation, and the enormous range of measurements used in engineering.',
explanation:[
'Start with objects you can count. The symbols 0 through 9 are digits; a number can contain several digits. Our base-ten system bundles ten ones into one ten, ten tens into one hundred, and so on. In 4,072, the 4 represents four thousands, the 0 holds an empty hundreds place, the 7 represents seven tens, and the 2 represents two ones. The zero keeps the other digits in their correct positions.',
'Compare whole numbers by their highest place first. Between two four-digit numbers, compare thousands, then hundreds if needed, and continue. Rounding answers a different question: which convenient nearby number should represent this quantity approximately? To round to the nearest hundred, locate the neighboring hundreds and find which is closer. An estimate is useful precisely because you know what detail you have temporarily discarded.',
'Keep exact counts separate from approximate measurements. A box can contain exactly 37 bolts, while a measured length of about 37 millimeters is limited by the instrument and method. For now, write approximately when you round. Before performing a long calculation, make an easy estimate that can catch an answer with a missing zero or an implausible size.'
],worked:[W('Read and round an inventory','A store records 4,072 washers.', ['Expand the number: 4,000 + 0 + 70 + 2.','The neighboring hundreds are 4,000 and 4,100.','The distances are 72 and 28, so 4,100 is nearer.'],'4,072 exactly; approximately 4,100 to the nearest hundred.','The rounded value differs by 28, less than half of one hundred.')],
pitfalls:['Ignoring an internal zero changes place values.','Rounding too early can erase information needed by a later calculation.'],engineering:'Inventories and measurements both become inputs to engineering calculations. Knowing their scale helps you notice transcription and unit errors.',reflection:'Explain why the same digit 7 means different amounts in 70, 700, and 7,000.',quiz:Q('What is the value of the digit 6 in 26,041?',['6','60','600','6,000'],'d','The 6 occupies the thousands place, so it represents six thousand.'),sources:[S('p','1-1-introduction-to-whole-numbers','whole numbers and place value')]},
{id:'addition-subtraction',stage:'arithmetic',order:2,title:'Addition, subtraction, and regrouping',subtitle:'Combine quantities, find changes, and check by reversing.',prerequisites:['place-value'],
why:'Most budgets begin with what you have, what arrives, and what leaves. Regrouping is a consequence of place value rather than an unexplained pencil trick.',
explanation:[
'Addition combines amounts; subtraction can remove an amount or measure the difference between two amounts. Write the story before choosing an operation. If a shelf begins with 58 parts and receives 27 more, addition answers the new total. If it must hold 100 parts, subtraction answers how many more are needed. These are different questions about the same quantities.',
'When adding vertically, align ones with ones and tens with tens. If a column contains ten or more ones, exchange ten ones for a ten. Subtraction uses the same exchange in reverse: one ten may be represented as ten ones without changing the total quantity. This is why regrouping works. You have changed the representation, not invented or removed an amount.',
'Addition is commutative: changing the order of two addends preserves the sum. Subtraction is not: 9 − 4 differs from 4 − 9. A powerful check is to reverse the operation. If A − B = C, then B + C should equal A. An estimate provides another check: subtracting about 300 from about 700 should leave about 400, not several thousand.'
],worked:[W('Track a small-parts bin','Start with 406 clips, receive 187, then issue 258.', ['Add arrivals: 406 + 187 = 593.','Subtract the issue: 593 − 258 = 335.','Interpret 335 as the number still in the bin, not the amount issued.'],'335 clips remain.','335 + 258 = 593, and 593 − 187 = 406; both reversed steps restore the earlier totals.')],
pitfalls:['Aligning digits by the left edge instead of by place value.','Subtracting the smaller digit from the larger in every column regardless of their positions.'],engineering:'A mass or material budget is a record of additions and removals. Clear accounting boundaries matter as much as accurate subtraction.',reflection:'Describe the exchange needed to subtract 8 ones when your ones column initially contains only 3.',quiz:Q('A kit contains 325 pieces. Add 79 and remove 146. How many remain?',['258','100','550','246'],'a','325 + 79 = 404, then 404 − 146 = 258. Reversing the subtraction confirms the result.'),sources:[S('p','1-2-add-whole-numbers','addition'),S('p','1-3-subtract-whole-numbers','subtraction')]},
{id:'multiplication-division',stage:'arithmetic',order:3,title:'Multiplication, division, and remainders',subtitle:'Understand groups before memorizing shortcuts.',prerequisites:['addition-subtraction'],
why:'Equal groups appear in repeated parts, packaging, costs, and production. Division helps distinguish the size of each group from the number of groups.',
explanation:[
'For whole numbers, multiplication can summarize equal-sized groups. Six trays holding eight pieces each contain 6 × 8 pieces. A rectangular array makes the same fact visible as six rows of eight. This picture also explains why reversing the factors gives the same product: rotate the array and rows become columns. Knowing small multiplication facts makes later work easier, but their meaning remains important.',
'Division asks either how many groups fit or how much belongs in each group. For 48 pieces shared equally among six trays, 48 ÷ 6 gives eight pieces per tray. For 48 pieces packed eight per tray, 48 ÷ 8 gives six trays. The numbers may look similar, but the units and question tell you what the quotient means.',
'Sometimes whole groups leave a remainder. The identity total = divisor × quotient + remainder gives a check, with the remainder smaller than a positive divisor. Context decides what to do with it. If passengers need seats, a partial final vehicle still requires another vehicle. If you are cutting complete fixed-length pieces, a leftover segment does not become an extra complete piece. Division by zero is undefined; there is no finite group count that makes zero-sized groups total a positive amount.'
],worked:[W('Package complete trays','Pack 137 components into trays holding 12 each.', ['12 × 11 = 132, leaving 137 − 132 = 5.','Therefore 11 trays can be completely filled, with 5 components left.','If every component must be placed in a tray, provide a twelfth tray.'],'11 full trays and 5 loose components; 12 trays to hold everything.','12 × 11 + 5 = 137, and the remainder 5 is less than 12.')],
pitfalls:['Reporting a remainder without interpreting its units.','Assuming that every division problem calls for rounding the same way.'],engineering:'Repeated components turn individual quantities into totals. Packaging and capacity calculations require a clear decision about incomplete groups.',reflection:'Give two different stories that both use 24 ÷ 6 but ask for different quantities.',quiz:Q('How many whole 7 cm pieces can be cut from 60 cm, ignoring cutting loss?',['9','8','8.57','7'],'b','Eight pieces use 56 cm and leave 4 cm. A ninth complete piece would require 63 cm.'),sources:[S('p','1-4-multiply-whole-numbers','multiplication'),S('p','1-5-divide-whole-numbers','division')]},
{id:'order-of-operations',stage:'arithmetic',order:4,title:'Grouping, powers, and order of operations',subtitle:'Notation needs one agreed meaning.',prerequisites:['multiplication-division'],
why:'A correct formula is useful only if you read its structure correctly. Grouping lets a short expression preserve a sequence of decisions without ambiguity.',
explanation:[
'Parentheses tell you which pieces form a single quantity. Compare 4 × (3 + 2) with 4 × 3 + 2. The first makes four copies of the whole five-unit bundle; the second makes four copies of three and then adds two. They describe different processes, so their answers should differ. A fraction bar also groups its complete numerator and denominator.',
'A positive whole-number exponent means repeated multiplication: 3² is 3 × 3, not 3 × 2. Evaluate grouping first, then exponents, then multiplication and division from left to right, then addition and subtraction from left to right. Multiplication does not automatically happen before division; they share a priority. Similarly, addition and subtraction share a priority. A mnemonic is helpful only when you keep those paired levels together.',
'Write intermediate steps that preserve equality. Each expression connected by an equals sign must have the same value as the others. If you change just one grouped piece, leave the rest visible. This habit prevents the common error of dropping a term while concentrating on a difficult operation. For a calculator, enter parentheses explicitly instead of assuming it understands the story you intended.'
],worked:[W('Read the structure first','Evaluate 30 − 2 × (4 + 1)² ÷ 5.', ['Inside parentheses, 4 + 1 = 5.','Square the grouped result: 5² = 25.','Multiply and divide left to right: 2 × 25 ÷ 5 = 50 ÷ 5 = 10.','Finish the subtraction: 30 − 10 = 20.'],'20','The multiplied-and-divided portion equals 10; subtracting it from 30 leaves 20.')],
pitfalls:['Reading 3² as 6.','Using a mnemonic to do all multiplication before any division, even when division appears first.'],engineering:'A programmed equation follows syntax, not intention. Explicit grouping is part of communicating a model correctly.',reflection:'Invent parentheses that change the value of 8 + 4 × 2, and explain the new grouping.',quiz:Q('Evaluate 24 ÷ 6 × 2 + 1.',['3','9','2','5'],'b','Division and multiplication proceed left to right: 24 ÷ 6 = 4, then 4 × 2 = 8, then add 1.'),sources:[S('p','2-1-use-the-language-of-algebra','exponents and order of operations')]},
{id:'fraction-meaning-addition',stage:'arithmetic',order:5,title:'Fractions and equal-sized pieces',subtitle:'Rename the units before combining them.',prerequisites:['multiplication-division'],
why:'Fractions describe usable amounts, not merely exercises. Their logic prepares you for ratios, algebraic expressions, and quantities smaller than one.',
explanation:[
'In 3/5, the denominator 5 says the whole is divided into five equal pieces; the numerator 3 counts three of those pieces. Equal size is essential. A fraction also represents division, so 3/5 means 3 divided by 5. Fractions can exceed one: 7/4 contains seven quarter-sized pieces, equivalent to one whole and three quarters. The whole being referenced must be identified before two shares can be meaningfully compared.',
'Equivalent fractions describe the same amount with different piece sizes. Multiplying numerator and denominator by the same nonzero number changes the naming, not the value: 2/3 = 8/12. This works because you are multiplying the fraction by a form of one. To simplify a fraction, divide its numerator and denominator by a common factor. The fraction has not become a smaller quantity merely because its written numbers got smaller.',
'For addition or subtraction, first use the same piece size. Thirds and quarters cannot be directly counted together any more than meters and centimeters can. A common denominator supplies that shared unit. You then add or subtract the numerators while keeping the denominator. Draw a strip if the procedure feels arbitrary, and estimate whether the result should be less than one, about one, or more than one.'
],worked:[W('Combine two measured shares','Add 2/3 liter and 1/4 liter.', ['Choose twelfths because 12 is divisible by both 3 and 4.','Rewrite 2/3 as 8/12 and 1/4 as 3/12.','Add the counts of twelfths: 8/12 + 3/12 = 11/12.'],'11/12 liter','The answer is greater than 2/3 but less than 1, which agrees with a drawing of the two shares.')],
pitfalls:['Adding denominators gives a new piece size and usually the wrong amount.','Comparing shaded fractions of differently sized wholes without accounting for the wholes.'],engineering:'Fill fractions, fractional hours, and proportions of materials require a stable meaning for the denominator.',reflection:'Explain why 3/6 and 1/2 occupy the same point on a number line.',quiz:Q('What is 3/4 − 1/6?',['2/2','7/12','1/2','2/10'],'b','Use twelfths: 3/4 = 9/12 and 1/6 = 2/12, giving 7/12.'),sources:[S('p','4-1-visualize-fractions','fraction meaning'),S('p','4-5-add-and-subtract-fractions-with-different-denominators','adding and subtracting fractions')]},
{id:'fraction-products-quotients',stage:'arithmetic',order:6,title:'Multiplying and dividing fractions',subtitle:'A fraction can scale an amount or name a group size.',prerequisites:['fraction-meaning-addition'],
why:'Multiplication by a fraction models taking a portion. Division by a fraction asks how many smaller portions fit, a pattern that reappears in rates and algebra.',
explanation:[
'Taking two thirds of three quarters means taking a portion of an amount that is already fractional. Multiply the numerators and denominators: (2/3)(3/4) = 6/12 = 1/2. A rectangle divided in two directions can show why the denominators multiply. Multiplication by a positive number below one makes a positive amount smaller; this is not a violation of multiplication but an extension beyond repeated whole groups.',
'Division asks for the number of divisor-sized groups in the dividend. For 3 ÷ (1/4), there are four quarter-sized groups in each whole, hence twelve in three wholes. Multiplying by the reciprocal counts those groups efficiently: a ÷ (b/c) = a(c/b), provided the divisor is nonzero. The reciprocal of a nonzero number multiplies with it to make one; zero has no reciprocal.',
'Convert mixed numbers to improper fractions before multiplying or dividing. Two and one half is 5/2, not 2 × 1/2. Cancel common factors across products when convenient, but do not cancel parts of sums. Finally, interpret the answer: a fractional number of portions may be allowed for liquid, whereas a count of complete rigid parts may require a whole-number answer and a leftover.'
],worked:[W('Use part of a fractional supply','Take 3/5 of a 5/6-liter supply.', ['Write the product (3/5)(5/6).','Multiply to get 15/30, then simplify by dividing top and bottom by 15.'],'1/2 liter','Half a liter is smaller than the original 5/6 liter, as a three-fifths share should be.'),W('Count portions','Divide 3/2 liters into portions of 3/8 liter.', ['Write (3/2) ÷ (3/8).','Multiply by the reciprocal: (3/2)(8/3) = 4.'],'4 portions','Four portions of 3/8 liter total 12/8 = 3/2 liters.')],
pitfalls:['Flipping the first fraction instead of the divisor.','Assuming multiplication always increases, or division always decreases, a positive amount.'],engineering:'Portioning materials and applying scale factors use these same operations; the units explain what the result counts.',reflection:'Why does dividing by one half double a positive number?',quiz:Q('What is (5/6) ÷ (5/12)?',['1/2','25/72','2','10/18'],'c','Multiply by 12/5. The fives cancel and 12/6 = 2.'),sources:[S('p','4-2-multiply-and-divide-fractions','fraction multiplication and division')]},
{id:'decimal-operations',stage:'arithmetic',order:7,title:'Decimals, fractions, and realistic size',subtitle:'The base-ten system continues below one.',prerequisites:['place-value','fraction-products-quotients'],
why:'Measurements and calculator displays commonly use decimals. Connecting them to fractions prevents decimal-point placement from becoming guesswork.',
explanation:[
'Moving one place right divides the place value by ten. After the decimal point come tenths, hundredths, and thousandths. Thus 0.37 means 37/100, while 0.037 means 37/1,000. Trailing zeros after the decimal can leave the numerical value unchanged: 0.5 = 0.50. The values are equal even though, in a measurement context, the written precision may communicate additional information.',
'Add and subtract decimals by aligning decimal points so equal places line up. Multiplication follows the fraction meaning: 0.2 × 0.3 = (2/10)(3/10) = 6/100 = 0.06. Division may be rewritten by multiplying both dividend and divisor by the same power of ten. For example, 1.2 ÷ 0.3 equals 12 ÷ 3 because both quantities have been scaled equally.',
'A decimal is not automatically approximate. A terminating decimal such as 0.125 equals 1/8 exactly. Some fractions have repeating decimal expansions; writing 1/3 as 0.333 truncates it and therefore gives an approximation. Keep an exact fraction when it is convenient, or retain extra calculator digits until the final report. Always estimate first: multiplying a quantity by 0.4 should produce less than half of it.'
],worked:[W('Total a length of identical segments','There are 6 segments, each 0.35 m long, with no gaps.', ['Write 6 × 0.35 m.','Think of 0.35 as 35 hundredths; six copies are 210 hundredths.','210/100 = 2.10.'],'2.1 m','Each segment is between 0.3 and 0.4 m, so the total must lie between 1.8 and 2.4 m.')],
pitfalls:['Treating 0.9 as smaller than 0.12 because 9 is smaller than 12.','Reporting a rounded decimal with an equals sign when the value is only approximate.'],engineering:'A misplaced decimal in a dimension changes the physical size. Estimation is a quick defense before detailed checking.',reflection:'Explain why 0.08 is eight hundredths and not eight tenths.',quiz:Q('Evaluate 2.4 ÷ 0.06.',['0.4','4','40','400'],'c','Multiply both quantities by 100: 240 ÷ 6 = 40. Multiplying 40 by 0.06 returns 2.4.'),sources:[S('p','5-2-decimal-operations','decimal operations'),S('p','5-3-decimals-and-fractions','decimals and fractions')]},
{id:'ratios-rates-percents',stage:'arithmetic',order:8,title:'Ratios, rates, and percentages',subtitle:'Compare quantities using a clearly named base.',prerequisites:['decimal-operations'],
why:'Comparisons become meaningful when they share a basis. These tools connect ordinary arithmetic to speed, efficiency, density, and proportions.',
explanation:[
'A ratio compares quantities by division. A red-to-blue count of 2:3 means two red items for each three blue items; it does not mean two out of three total items are red. There are five equal shares in the total, so the red share is 2/5. State which quantities the two positions refer to, because reversing a ratio changes its meaning.',
'A rate often compares different kinds of quantity, such as meters per second. “Per” means for each one unit of the denominator. Dividing total distance by elapsed time gives average speed. It does not prove the vehicle moved steadily throughout the interval. A unit rate makes comparisons easier: divide both quantities by the denominator to put it on a one-unit basis.',
'Percent means per hundred and can be written as a fraction or decimal. Twenty-five percent is 25/100 = 0.25. To find a percentage of an amount, multiply by that decimal. To find what percent one amount is of another, divide the part by the named base and multiply by 100%. Always ask “percent of what?” A reduction amount and the remaining amount answer different questions.'
],worked:[W('Find a rate','A model vehicle travels 84 m in 28 s.', ['Average speed = distance/time.','84 m ÷ 28 s = 3 m/s.'],'3 m/s average speed','At a constant 3 m/s, 28 seconds would produce 84 m; the average is consistent.'),W('Find a remaining amount','A 240 g component is made 15% lighter.', ['Removed mass = 0.15 × 240 = 36 g.','Remaining mass = 240 − 36 = 204 g.'],'204 g','The result is 85% of 240 g, and 0.85 × 240 = 204.')],
pitfalls:['Confusing a part-to-part ratio with a part-to-whole fraction.','Calling the amount removed the new total.'],engineering:'Mass fractions and average operating rates help compare designs, provided the measurements and reference quantities are stated.',reflection:'Explain why 20% of 50 differs from 20% of 200 even though both say twenty percent.',quiz:Q('In a 3:2 red-to-blue mixture, what percentage of the total is red?',['30%','60%','150%','40%'],'b','There are five shares altogether; three are red. The red fraction is 3/5 = 60%.'),sources:[S('p','5-6-ratios-and-rate','ratios and rates'),S('p','6-1-understand-percent','percentages')]}
];

const prealgebra = [
{id:'signed-numbers',stage:'prealgebra',order:9,title:'Negative numbers and absolute value',subtitle:'A sign can identify direction relative to a reference.',prerequisites:['order-of-operations','decimal-operations'],
why:'Directions, changes, and differences need more than positive numbers. A consistent sign convention lets arithmetic track opposing effects.',
explanation:[
'A number line extends to both sides of zero. Positive numbers lie to the right and negative numbers to the left. Farther right means greater, so −2 is greater than −7 even though 7 is the larger absolute value. Absolute value measures distance from zero: |−7| = 7. Distance is nonnegative; a signed position can be negative because it includes direction from a chosen origin.',
'Adding a signed number represents a directed change. Starting at −3 and adding +8 lands at 5. Subtracting a number is equivalent to adding its opposite: 4 − (−2) = 4 + 2. You can justify this by asking which number added to −2 gives 4. For products and quotients, matching signs give a positive result and differing signs give a negative result. These rules preserve the distributive property and the existing arithmetic relationships.',
'Separate a negative sign from the role of subtraction. In −5 − 2, the first sign belongs to a negative number and the second describes an operation. Parentheses keep negative inputs clear when substituting later: (−3)² = 9, whereas −3² means −(3²) = −9 under the standard convention. Draw the number line and state the reference before interpreting a negative physical answer.'
],worked:[W('Track a vertical displacement','Choose upward positive. Begin at 2 m, move down 7 m, then up 3 m.', ['Represent the changes as −7 m and +3 m.','Compute 2 + (−7) + 3 = −2.','The final coordinate is 2 m below the origin.'],'Final position: −2 m; total travel: 10 m.','The net change is −4 m, and 2 − 4 = −2. Travel distance adds the magnitudes 7 + 3.')],
pitfalls:['Confusing distance traveled with signed displacement.','Using the sign of the larger written digit rather than the actual arithmetic relationship.'],engineering:'A coordinate convention makes position and velocity components interpretable. The sign is useful information, not automatically an error.',reflection:'Explain the difference between a final coordinate of −2 m and a displacement of −2 m.',quiz:Q('Evaluate −4 − (−9).',['−13','−5','5','13'],'c','Subtracting −9 means adding +9: −4 + 9 = 5.'),sources:[S('p','3-1-introduction-to-integers','integers and absolute value'),S('p','3-3-subtract-integers','subtracting integers')]},
{id:'factors-multiples',stage:'prealgebra',order:10,title:'Factors, multiples, and common structure',subtitle:'Break integers into pieces that multiply.',prerequisites:['multiplication-division','fraction-meaning-addition'],
why:'Factoring explains efficient fraction simplification and common denominators. It also prepares you for factoring algebraic expressions later.',
explanation:[
'A factor divides a whole number evenly. Since 18 = 3 × 6, both 3 and 6 are factors of 18. A multiple is obtained by multiplying a number by a whole number: 18, 36, and 54 are positive multiples of 18. These words describe opposite directions in the same multiplication relationship. Distinguish a factor inside a number from a multiple built from it.',
'A prime number is an integer greater than one whose positive factors are only one and itself. Repeatedly splitting a composite integer into factors eventually produces a prime factorization. Order does not matter: 60 = 2 × 2 × 3 × 5. The number 1 is neither prime nor composite. A prime factorization is useful because common pieces become visible instead of being guessed.',
'The greatest common factor uses the shared prime factors with the smaller available counts. The least common multiple uses every required prime factor with the larger count. For fraction simplification you seek factors common to numerator and denominator. For a convenient common denominator you seek a number that both denominators divide. Understanding that distinction is more reliable than applying one memorized procedure to every fraction problem.'
],worked:[W('Find shared and combined requirements','Find the greatest common factor and least common multiple of 18 and 24.', ['18 = 2 × 3², while 24 = 2³ × 3.','The shared minimum counts give GCF = 2 × 3 = 6.','The combined maximum counts give LCM = 2³ × 3² = 72.'],'GCF = 6; LCM = 72.','Both numbers divide by 6. Also, 72/18 = 4 and 72/24 = 3, so 72 is a multiple of each.')],
pitfalls:['Calling 1 a prime number.','Using a common factor when a common multiple is needed for a denominator.'],engineering:'Repeated timing and modular grouping can become integer factor problems. The immediate benefit is dependable fraction and algebra work.',reflection:'Why can the least common multiple be smaller than the product of two numbers?',quiz:Q('What is the least common multiple of 8 and 12?',['4','20','24','96'],'c','8 = 2³ and 12 = 2² × 3. Combining the required factors gives 2³ × 3 = 24.'),sources:[S('p','2-4-find-multiples-and-factors','factors and multiples'),S('p','2-5-prime-factorization-and-the-least-common-multiple','prime factorization')]},
{id:'variables-expressions',stage:'prealgebra',order:11,title:'Variables and translating a situation',subtitle:'Give each quantity a name and a job.',prerequisites:['signed-numbers','ratios-rates-percents'],
why:'A formula expresses a reusable relationship. Variables let you solve a family of related situations rather than memorize separate numerical answers.',
explanation:[
'A variable is a symbol representing a quantity. It may be unknown, changing, or a value you choose. Define the symbol in words and include units when appropriate. In a simple model E = Pt, P may mean power in watts, t duration in hours, and E energy in watt-hours. The same letter can mean something different in another problem; its definition controls its meaning.',
'An expression represents a value, such as 3n + 5. An equation states equality between expressions, such as 3n + 5 = 20. Evaluating an expression means substituting a specified input and calculating. Solving an equation means finding inputs that make its claim true. Keep those tasks separate: an expression alone does not always ask you to find a variable.',
'Translate relationships rather than hunting for isolated keywords. “Five fewer than twice n” means 2n − 5, because five is removed from the doubled amount. “Five less twice n” would describe a different order. Test your translation with an easy invented input and tell the story back in words. A concrete check often catches a reversed subtraction or a missing pair of parentheses before algebra starts.'
],worked:[W('Write a modular mass model','A carrier has a fixed mass of 7 kg and holds n identical 2 kg modules.', ['Name M as the total mass in kilograms.','The modules contribute 2n kilograms, so M = 7 + 2n.','At n = 4, substitute to obtain M = 7 + 2(4) = 15.'],'M = 7 + 2n; four modules give 15 kg.','With zero modules the formula gives the empty carrier mass of 7 kg. Adding one module increases the total by 2 kg.')],
pitfalls:['Interpreting adjacent symbols such as 2n as a two-character label instead of multiplication.','Substituting a negative input without parentheses.'],engineering:'Every model needs defined variables and compatible units. Writing those definitions is part of the mathematics, not optional decoration.',reflection:'Explain the difference between evaluating 4x + 1 at x = 3 and solving 4x + 1 = 3.',quiz:Q('Which expression means “three times the sum of x and four”?',['3x + 4','3(x + 4)','x + 12','3 + x + 4'],'b','The entire sum x + 4 is multiplied by three, so it must be grouped.'),sources:[S('p','2-2-evaluate-simplify-and-translate-expressions','evaluating and translating expressions')]},
{id:'distribute-combine',stage:'prealgebra',order:12,title:'Distribute and combine like terms',subtitle:'Change the form while preserving the value.',prerequisites:['variables-expressions','signed-numbers'],
why:'Simplifying an expression reduces clutter so you can see its relationship. The same principles support equation solving, polynomial work, and later calculus.',
explanation:[
'The distributive property says a(b + c) = ab + ac. Imagine a bundles, each containing b pieces of one kind and c of another. Every part of the bundle is repeated, so the multiplier reaches every term. A rectangle partitioned into two widths provides another picture. The rule also works with subtraction because subtraction can be treated as addition of a negative term.',
'Like terms have the same variable part, including its exponents. Three x-units plus five x-units become eight x-units: 3x + 5x = 8x. But x and x² represent different kinds of expressions, so they cannot be combined into a single multiple of x. Constants can be combined with other constants. Think of collecting comparable quantities rather than deleting repeated letters.',
'A leading minus sign applies to the complete grouped quantity: −(x − 4) = −x + 4. To simplify safely, first distribute through parentheses, then group matching terms while carrying their signs, then add coefficients. You can verify an identity at a chosen input to catch an error, although one successful numerical check alone does not prove it holds for every input. The distributive property provides the general justification.'
],worked:[W('Simplify a grouped calculation','Simplify 3(2x − 5) − 2(x + 1).', ['Distribute the first factor: 6x − 15.','Distribute the negative second factor: −2x − 2.','Combine like terms: (6x − 2x) + (−15 − 2).'],'4x − 17','At x = 2, the original is 3(−1) − 2(3) = −9, and 4(2) − 17 is also −9.')],
pitfalls:['Multiplying only the first term inside parentheses.','Combining x and x² as if they had the same variable part.'],engineering:'An expanded budget exposes individual contributions, while a grouped expression may show repeated assemblies. Both forms can describe the same design.',reflection:'Explain why 2x + 3x can be combined but 2x + 3 cannot.',quiz:Q('Simplify 4(x − 2) + 3x.',['7x − 2','7x − 8','4x − 5','12x − 8'],'b','Distribute to get 4x − 8 + 3x, then combine the x terms.'),sources:[S('e','1-9-properties-of-real-numbers','the distributive property')]},
{id:'equation-balance',stage:'prealgebra',order:13,title:'Equality and one- or two-step equations',subtitle:'An equation is a relationship to preserve.',prerequisites:['distribute-combine'],
why:'Solving begins with a simple principle: make valid changes to both sides. This explains the steps and scales to unfamiliar formulas.',
explanation:[
'An equals sign means the expressions on its two sides have the same value. Solving identifies the variable values for which that statement is true. For x + 7 = 19, subtracting seven from both sides preserves the equality and gives x = 12. The common phrase “move the seven” hides the operation; naming the subtraction makes the reasoning easier to check.',
'Use inverse operations to isolate the unknown. Addition and subtraction undo one another. Multiplication and division by the same nonzero number undo one another. In 3x + 4 = 25, first remove the added four, then undo multiplication by three. The order reflects how the expression was built. Dividing by zero is never an allowed inverse operation.',
'A proposed answer should be substituted into the original equation, not only into your last rewritten line. A mistake made earlier could make the last line look correct while losing the original relationship. In a word problem, also interpret the units and whether the answer is physically meaningful. Solving an equation and answering the original question are connected but distinct responsibilities.'
],worked:[W('Find the duration','A hypothetical instrument uses 8 Wh during setup and then 6 Wh for each hour of operation. Total energy is 38 Wh.', ['Let t be the operating time in hours.','Write 8 + 6t = 38.','Subtract 8 from each side: 6t = 30.','Divide both sides by 6: t = 5.'],'5 hours','Setup uses 8 Wh and five operating hours use 30 Wh, totaling 38 Wh.')],
pitfalls:['Changing only one side of an equality.','Stopping at an algebraic number without stating what it measures.'],engineering:'Rearranging a measured relationship often provides the quantity you need. Transparent steps make a calculation reviewable by someone else.',reflection:'Why does subtracting the same amount from both sides preserve equality?',quiz:Q('Solve 5x − 7 = 28.',['5','7','21','35'],'b','Add 7 to obtain 5x = 35, then divide by 5. Substitution gives 35 − 7 = 28.'),sources:[S('e','2-1-solve-equations-using-the-subtraction-and-addition-properties-of-equality','properties of equality'),S('e','2-2-solve-equations-using-the-division-and-multiplication-properties-of-equality','multiplication and division in equations')]},
{id:'powers-roots-scientific',stage:'prealgebra',order:14,title:'Powers, roots, and scientific notation',subtitle:'Keep large and small scales understandable.',prerequisites:['order-of-operations','signed-numbers','factors-multiples'],
why:'Scientific notation makes scale visible. Exponent and root rules explain how to manipulate it without losing zeros or signs.',
explanation:[
'For positive integer exponents, a power repeats multiplication. Multiplying powers with the same base adds their exponents because it joins the repeated factors: 2³ × 2² = 2⁵. Dividing them subtracts exponents when the base is nonzero. To keep this pattern consistent, a nonzero base to power zero equals one, and a negative exponent represents a reciprocal. Thus 10⁻³ = 1/1,000, not −1,000.',
'A square root reverses squaring for nonnegative real inputs. The symbol √9 denotes the principal, nonnegative root 3. The equation x² = 9, however, has both 3 and −3 as solutions. Those are different questions. Some roots are irrational and cannot be written as a ratio of integers; √2 is exact, while 1.414 is an approximation to it.',
'Scientific notation writes a positive quantity as a coefficient from 1 up to but not including 10 times a power of ten. For negative quantities, apply the same size rule to the magnitude of the coefficient. Separate the coefficient arithmetic from the power-of-ten arithmetic, then normalize the result if needed. Use scientific notation to compare orders of magnitude before worrying about small differences in coefficients.'
],worked:[W('Combine a large rate with a short duration','Evaluate (4 × 10⁶)(3 × 10⁻⁴).', ['Multiply coefficients: 4 × 3 = 12.','Add exponents on ten: 6 + (−4) = 2.','12 × 10² is correct but not normalized; rewrite it as 1.2 × 10³.'],'1.2 × 10³ = 1,200','Four million times 0.0003 equals 1,200, confirming the scale.')],
pitfalls:['Applying exponent-addition rules to sums instead of products.','Treating √25 as ±5; the ± belongs when solving x² = 25.'],engineering:'Sensor signals and space-related distances span many powers of ten. A scale estimate can detect a unit conversion error immediately.',reflection:'Explain why 10⁰ must equal one if dividing powers is to follow the same pattern.',quiz:Q('Which is scientific notation for 0.00072?',['7.2 × 10⁻⁴','7.2 × 10⁴','72 × 10⁻⁴','0.72 × 10⁻³'],'a','Moving from 7.2 to 0.00072 requires division by 10,000, or multiplication by 10⁻⁴.'),sources:[S('e','6-7-integer-exponents-and-scientific-notation','integer exponents and scientific notation'),S('p','5-7-simplify-and-use-square-roots','square roots')]},
{id:'units-conversions',stage:'prealgebra',order:15,title:'Units and conversion factors',subtitle:'Let the units participate in the calculation.',prerequisites:['ratios-rates-percents','powers-roots-scientific'],
why:'A measured quantity includes both a number and a unit. Writing units makes conversions understandable and provides an independent way to inspect a formula.',
explanation:[
'Meters and centimeters describe the same kind of quantity at different scales. Since 1 m = 100 cm, the ratio 100 cm/1 m equals one. Multiplying a length by this ratio changes its description without changing its physical size. Put the unwanted unit in the denominator so it cancels. This is more reliable than remembering whether a particular conversion should multiply or divide.',
'Rates have units in both numerator and denominator. Converting kilometers per hour to meters per second needs a distance conversion and a time conversion. Area and volume require powers of a length conversion: 1 m² = (100 cm)² = 10,000 cm². Also distinguish physical dimensions: mass and force are different quantities even if everyday language sometimes blurs them.',
'Dimensional consistency is a useful filter, not a proof that a formula is right. Distance divided by time has speed units, whereas distance multiplied by time does not. Yet two different formulas can share the same units and still predict different values. After checking dimensions, check the model, the numbers, and the situation. Keep conversion factors visible until the final line, particularly when several scales are involved.'
],worked:[W('Express a speed in useful units','Convert 54 km/h to m/s.', ['Write 54 km/h × (1,000 m/1 km) × (1 h/3,600 s).','Cancel kilometers and hours; the remaining units are meters per second.','Calculate 54,000/3,600 = 15.'],'15 m/s','At 15 m/s for 3,600 seconds, distance is 54,000 m = 54 km.')],
pitfalls:['Converting square meters using only one factor of 100.','Dropping units early and hoping to reconstruct them at the end.'],engineering:'Interfaces between measurements, calculations, and software need agreed units. Dimensional reasoning is useful from the first lab onward.',reflection:'Show why multiplying watts by hours produces energy units, while dividing watts by hours does not.',quiz:Q('How many square centimeters equal 0.02 m²?',['2','20','200','2,000'],'c','Multiply by 10,000 cm²/m². The result is 200 cm².'),sources:[S('e','1-10-systems-of-measurement','measurement systems')]},
{id:'proportions-percent-change',stage:'prealgebra',order:16,title:'Proportions and changing percentages',subtitle:'First decide whether a constant ratio is justified.',prerequisites:['equation-balance','units-conversions'],
why:'Proportions turn a known comparison into a new estimate. Percentage changes also use multiplication, but their reference amount can change between steps.',
explanation:[
'A proportion states that two ratios are equal. If identical components have constant mass per component, a known count and total mass can predict another count. Keep corresponding quantities in corresponding positions: kilograms per component should equal kilograms per component. Cross-multiplication is a consequence of multiplying both sides by nonzero denominators; it is not a universal instruction whenever fractions appear.',
'Before scaling, ask whether the situation actually preserves a ratio. Buying twice as much material may double its mass, but doubling the side length of a three-dimensional object does not merely double its volume. A fixed setup charge can also break proportionality. A table or graph through the origin may help identify a direct proportion, but the physical assumptions still need to be stated.',
'An increase by p percent multiplies the starting amount by 1 + p/100; a decrease multiplies it by 1 − p/100. Successive changes multiply these factors. Equal percentage increases and decreases generally do not cancel, because the second percentage acts on a new base. Compare changes using both their absolute amount and their percentage of the specified original quantity.'
],worked:[W('Scale an identical-part estimate','Five identical brackets have total mass 1.5 kg. Estimate the mass of eight.', ['Mass per bracket is 1.5/5 = 0.3 kg.','Eight brackets have mass 8 × 0.3 = 2.4 kg.'],'2.4 kg','The ratio 2.4/8 equals the original 1.5/5.'),W('Apply successive changes','A quantity begins at 200, rises 10%, then falls 10%.', ['After the rise: 200 × 1.10 = 220.','After the fall: 220 × 0.90 = 198.'],'198, a net 1% decrease','The combined multiplier is 1.10 × 0.90 = 0.99.')],
pitfalls:['Scaling a relationship that includes a fixed offset as though it were proportional.','Adding opposite percentage changes and assuming the net change is zero.'],engineering:'Scaling estimates are useful when the relevant relationship is justified. Always label an estimate as conditional on its assumptions.',reflection:'What extra information would you need before scaling the mass of a hollow structure from its length alone?',quiz:Q('A value drops from 80 to 60. What is the percentage decrease from the original value?',['20%','25%','33⅓%','75%'],'b','The decrease is 20, and its original base is 80. Therefore 20/80 = 25%.'),sources:[S('p','6-5-solve-proportions-and-their-applications','proportions'),S('p','6-3-solve-sales-tax-commission-and-discount-applications','percentage applications')]}
];

const algebra = [
{id:'multistep-linear-equations',stage:'algebra',order:17,title:'Linear equations with several steps',subtitle:'Use a consistent strategy without hiding the reasons.',prerequisites:['equation-balance','fraction-products-quotients'],
why:'Real relationships rarely arrive as a single easy operation. A reliable strategy helps when fractions, parentheses, and variables appear on both sides.',
explanation:[
'Simplify each side first: distribute through parentheses and combine like terms. Then collect variable terms on one side and constant terms on the other by performing the same operation on both sides. Finally divide by the nonzero coefficient of the variable. Several valid orders may exist; clarity matters more than choosing the fewest written lines.',
'Fractions can be removed by multiplying every term on both sides by a common nonzero denominator. The word every is essential. For x/3 + 2 = 5, multiplying by three gives x + 6 = 15, not x + 2 = 15. If decimals are inconvenient, multiply the entire equation by a suitable power of ten. These are equivalent equations because the same nonzero multiplier acts on both sides.',
'Not every linear-looking equation has exactly one solution. If simplification produces a true statement such as 0 = 0, every value in the original domain is a solution. If it produces a contradiction such as 0 = 5, there is no solution. Do not manufacture a value for x when it has canceled. The final statement tells you how the two original expressions relate.'
],worked:[W('Clear fractions and solve','Solve (x − 2)/3 + x/2 = 6.', ['The common denominator is 6. Multiply every term by 6.','Obtain 2(x − 2) + 3x = 36.','Distribute and combine: 5x − 4 = 36.','Add 4 and divide by 5: x = 8.'],'x = 8','In the original, (8 − 2)/3 + 8/2 = 2 + 4 = 6.')],
pitfalls:['Multiplying only the fractional terms when clearing denominators.','Interpreting 0 = 0 as x = 0 instead of an identity.'],engineering:'Several contributions often appear on both sides of a balance. Methodical rearrangement keeps the meaning intact while revealing an unknown.',reflection:'Create one equation with no solution and one true for every real x, then explain the difference.',quiz:Q('Solve 4(x − 1) = 2x + 10.',['3','5','7','14'],'c','Expand to 4x − 4 = 2x + 10. Subtract 2x, add 4, and divide by 2 to get x = 7.'),sources:[S('e','2-5-solve-equations-with-fractions-or-decimals','equations with fractions and decimals'),S('e','2-3-solve-equations-with-variables-and-constants-on-both-sides','variables on both sides')]},
{id:'rearranging-formulas',stage:'algebra',order:18,title:'Rearrange a formula for what you need',subtitle:'The same relationship can answer different questions.',prerequisites:['multistep-linear-equations','units-conversions'],
why:'Engineering work constantly switches between known and unknown quantities. Symbolic rearrangement makes one carefully checked result reusable.',
explanation:[
'A formula is an equation connecting quantities. Solving it for a chosen symbol follows the same equality rules as solving a numerical equation. Treat the other symbols as known quantities while remembering that they may have restrictions. For d = vt, dividing by v gives t = d/v only when v is nonzero. Write that condition rather than silently discarding the zero case.',
'Keep grouped expressions intact until you have a reason to expand them. For A = b(h + k), first divide by b when b is nonzero, then subtract k to isolate h. You may also encounter an unknown in more than one term. Factor it before dividing: ax + bx = c becomes (a + b)x = c. Division requires a + b ≠ 0, not merely that a and b individually be nonzero.',
'Check a symbolic rearrangement in two complementary ways. Substitute it back into the original relationship and simplify. Also inspect units: a time found from distance divided by speed should carry time units. Numerical examples can catch a transcription error, but symbolic reasoning explains why the rearrangement works for every allowed set of inputs. State the physical assumptions separately from the algebra.'
],worked:[W('Solve a constant-acceleration relationship','Given v = u + at, solve for t when a ≠ 0. Then use v = 14 m/s, u = 2 m/s, a = 3 m/s².', ['Subtract u from both sides: v − u = at.','Divide by a: t = (v − u)/a.','Substitute compatible units: t = (14 − 2)/3 = 4.'],'t = (v − u)/a; the example gives 4 s.','Substitution gives 2 + 3(4) = 14 m/s. Velocity divided by acceleration has units of seconds.')],
pitfalls:['Losing parentheses around an entire numerator.','Ignoring the condition that a divisor must be nonzero.'],engineering:'The example assumes constant acceleration over the interval. A correct rearrangement does not establish that the physical model applies.',reflection:'What can the equation v = u + at tell you about t when a = 0?',quiz:Q('From E = Pt, solve for P when t ≠ 0.',['P = Et','P = E/t','P = t/E','P = E − t'],'b','Divide both sides by t. If energy is measured in Wh and time in h, the quotient is in W.'),sources:[S('e','2-6-solve-a-formula-for-a-specific-variable','solving formulas')]},
{id:'inequalities-constraints',stage:'algebra',order:19,title:'Inequalities and allowable choices',subtitle:'A requirement may define a range of answers.',prerequisites:['multistep-linear-equations'],
why:'Limits and requirements are often more useful than exact targets. Inequalities express what is permitted and make boundaries visible.',
explanation:[
'The symbols < and > describe strict comparisons; ≤ and ≥ include equality. Read a statement in words before manipulating it. A total mass at most 30 kg means M ≤ 30, whereas a mass below 30 kg means M < 30. On a number line, a filled endpoint includes the boundary and an open endpoint excludes it.',
'Adding or subtracting the same value preserves the inequality direction. Multiplying or dividing by a positive value does too. A negative multiplier reverses the direction: from 2 < 5, multiplication by −1 gives −2 > −5. Picture the number line reflecting about zero. This is why a sign change in inequality solving needs attention instead of being treated exactly like an equation.',
'Context can further restrict an algebraic interval. A number of complete modules must be a nonnegative integer, while a duration may vary continuously. Compound statements use “and” for simultaneous restrictions and “or” for alternative possibilities. For now, solve each condition, then ask which values satisfy the required combination. Test a value inside the proposed set and one outside it to check the direction.'
],worked:[W('Respect a mass allocation','An empty carrier has mass 9 kg. Each module adds 4 kg. Total mass must be at most 30 kg.', ['Let n be the number of modules: 9 + 4n ≤ 30.','Subtract 9: 4n ≤ 21.','Divide by 4: n ≤ 5.25.','Because n is a nonnegative whole-number count, the largest allowable count is 5.'],'At most 5 complete modules.','Five gives 29 kg; six gives 33 kg and exceeds the limit.')],
pitfalls:['Forgetting to reverse direction when dividing by a negative number.','Reporting a fractional count where the context requires whole items.'],engineering:'A feasible design satisfies its constraints. Whether additional reserve is needed is a separate engineering decision, not supplied by the inequality alone.',reflection:'Explain the difference between “at least five” and “more than five” on a number line.',quiz:Q('Solve −3x ≥ 12.',['x ≥ −4','x ≤ −4','x ≥ 4','x ≤ 4'],'b','Dividing both sides by −3 reverses the comparison, giving x ≤ −4.'),sources:[S('e','2-7-solve-linear-inequalities','linear inequalities')]},
{id:'coordinates-and-slope',stage:'algebra',order:20,title:'Coordinates, graphs, and slope',subtitle:'Read a graph as quantities with units.',prerequisites:['variables-expressions','signed-numbers','ratios-rates-percents'],
why:'Graphs let you inspect patterns that a table or formula can hide. Slope connects visual change with a numerical rate.',
explanation:[
'An ordered pair (x, y) gives a horizontal coordinate first and a vertical coordinate second. Choose an origin, axis directions, and scales. A point such as (−2, 3) means two coordinate units left of the origin and three up. If the axes represent time and distance, those coordinates have physical units and cannot be casually swapped.',
'For two distinct points with different x coordinates, slope is the change in y divided by the corresponding change in x: (y₂ − y₁)/(x₂ − x₁). Subtract in the same order in numerator and denominator. A positive slope rises as you move right; a negative slope falls. A horizontal line has zero slope, while a vertical line has undefined slope because its horizontal change is zero.',
'Slope is not usually y/x. That ratio agrees with a line’s slope only when the line passes through the origin and you use a nonzero x. Axis scale also affects visual steepness: stretching a graph vertically makes it look steeper without changing the underlying numerical relationship. Read labels and tick values instead of judging a rate by appearance alone.'
],worked:[W('Read a position change','A straight-line position model passes through (2 s, 7 m) and (6 s, 19 m).', ['Change in position is 19 − 7 = 12 m.','Corresponding change in time is 6 − 2 = 4 s.','Slope is 12/4 = 3 m/s.'],'3 m/s','Four seconds at a constant 3 m/s account for the 12 m position change.')],
pitfalls:['Reversing subtraction order in only one part of the slope fraction.','Confusing a zero slope with an undefined slope.'],engineering:'A position-time slope describes velocity over the interval. For curved data it is an average rate, not necessarily the instantaneous velocity.',reflection:'Why can a graph look steep while describing a small numerical rate?',quiz:Q('What is the slope through (1, 8) and (5, 0)?',['2','−2','−8','1/2'],'b','The vertical change is −8 and the horizontal change is 4, so slope is −2.'),sources:[S('e','4-1-use-the-rectangular-coordinate-system','coordinates'),S('e','4-4-understand-slope-of-a-line','slope')]},
{id:'linear-models',stage:'algebra',order:21,title:'Build and interpret a linear model',subtitle:'Separate the starting amount from the rate of change.',prerequisites:['coordinates-and-slope','rearranging-formulas'],
why:'A linear model is a useful first description when one quantity changes at a constant rate with another. Its two parameters have distinct jobs.',
explanation:[
'In y = mx + b, m is the slope and b is the output when x = 0. The y-intercept is the point (0, b), not just an isolated number on an unlabeled chart. A nonzero intercept often represents an initial quantity or fixed contribution. If b = 0, the model is a direct proportion; otherwise doubling x does not generally double y.',
'To build a line from two points, calculate its slope first. Substitute one known point into y = mx + b and solve for b. Then check the other point. Another equivalent form is y − y₁ = m(x − x₁), which emphasizes change relative to a known point. Different forms may make different questions easier without changing the line.',
'A mathematical line extends forever, but an applied model normally does not. A draining tank cannot contain negative water, and a sensor calibration may only be valid over its tested range. Distinguish interpolation, estimating between known inputs, from extrapolation beyond them. Even interpolation assumes the chosen model is appropriate; agreement with two points alone does not prove a physical process is linear.'
],worked:[W('Model a steady fill','A tank has 14 L at t = 2 min and 26 L at t = 6 min. Assume constant inflow.', ['Slope is (26 − 14)/(6 − 2) = 3 L/min.','Use V = 3t + b and the first point: 14 = 3(2) + b.','Thus b = 8 and V = 8 + 3t.','At t = 5 min, V = 8 + 15 = 23 L.'],'V = 8 + 3t; the estimate at five minutes is 23 L.','The model reproduces both given measurements. It must be restricted before the tank overflows or the flow changes.')],
pitfalls:['Calling every straight-line model a direct proportion.','Extrapolating past a physical boundary without checking the assumptions.'],engineering:'Simple calibration and operating models often begin with a line. Residual differences between predictions and measurements help assess whether it is adequate.',reflection:'In a model with a fixed initial amount, why does doubling time not necessarily double the total?',quiz:Q('A line has slope 4 and passes through (2, 11). What is its equation?',['y = 4x + 3','y = 4x + 11','y = 2x + 4','y = 4x − 3'],'a','Substitute the point: 11 = 4(2) + b, so b = 3.'),sources:[S('e','4-5-use-the-slope-intercept-form-of-an-equation-of-a-line','slope-intercept models'),S('e','4-6-find-the-equation-of-a-line','finding a line')]},
{id:'systems-of-equations',stage:'algebra',order:22,title:'Systems of equations',subtitle:'One answer must satisfy every condition.',prerequisites:['multistep-linear-equations','linear-models'],
why:'A count alone may not determine a design. Combining independent constraints can identify quantities that no single equation reveals.',
explanation:[
'A system groups equations that must hold simultaneously. With two unknowns, one equation often describes many pairs. A second independent equation can narrow the possibilities to a single pair. Graphically, two nonparallel lines meet at that solution. Parallel distinct lines have none, while two equations describing the same line have infinitely many.',
'Substitution replaces a variable with an equal expression from another equation. If x + y = 10, then y = 10 − x; insert that expression wherever y appears in the second equation. Elimination instead adds suitable multiples of equations so a variable cancels. Both methods preserve the condition that the original equations must be satisfied together.',
'Choose symbols with units and build each equation from a separate fact. A count equation and a mass equation are common teaching examples. Once you solve, substitute the pair into both originals. A pair that works in just one equation is not a system solution. Also inspect physical restrictions: an algebraic solution containing a negative count can reveal that the requested combination is impossible.'
],worked:[W('Identify two types of modules','A kit has 9 modules. Light modules weigh 2 kg and heavy modules 5 kg; total mass is 30 kg.', ['Let L and H be the respective counts: L + H = 9 and 2L + 5H = 30.','Multiply the count equation by 2: 2L + 2H = 18.','Subtract it from the mass equation: 3H = 12, so H = 4.','Then L = 9 − 4 = 5.'],'5 light modules and 4 heavy modules.','Counts total 9; mass is 5(2) + 4(5) = 30 kg.')],
pitfalls:['Solving one equation and forgetting the second.','Treating two copies of the same relationship as independent information.'],engineering:'Balance equations and shared design requirements produce systems. Later linear algebra generalizes the same reasoning to many quantities at once.',reflection:'Describe what it means physically if a count-and-mass system has no nonnegative whole-number solution.',quiz:Q('Solve x + y = 12 and x − y = 4. What is x?',['4','6','8','16'],'c','Adding the equations gives 2x = 16, so x = 8 and y = 4.'),sources:[S('e','5-2-solving-systems-of-equations-by-substitution','substitution'),S('e','5-3-solve-systems-of-equations-by-elimination','elimination')]},
{id:'polynomials-and-factoring',stage:'algebra',order:23,title:'Polynomial operations and factoring',subtitle:'Expand to expose terms; factor to expose products.',prerequisites:['distribute-combine','powers-roots-scientific'],
why:'Polynomial expressions become building blocks for functions and equations. Recognizing their structure is more useful than treating every line as a new puzzle.',
explanation:[
'A polynomial combines terms whose variable exponents are nonnegative integers. Examples include 4x² − 3x + 7 and 2x³. Adding polynomials means collecting like terms. Multiplication applies the distributive property repeatedly: every term in one factor multiplies every term in the other. Keep a simple grid or organized lines so no cross product disappears.',
'Factoring reverses expansion. First look for a greatest common factor: 6x² + 9x = 3x(2x + 3). For a monic quadratic x² + bx + c, seek two numbers whose sum is b and whose product is c. Their binomial factors explain the middle term through distribution. Always multiply the proposed factors back out; an attractive pattern is not enough.',
'Important patterns include a² − b² = (a − b)(a + b) and (a + b)² = a² + 2ab + b². The cross term in a square records two rectangular regions in an area picture. A sum of squares does not follow the difference-of-squares rule over the real numbers. Not every polynomial factors into convenient integer factors, so recognizing when a method does not apply is part of fluency.'
],worked:[W('Expand and then recognize the structure','Expand (x + 4)(x + 2).', ['Distribute x across the second factor: x² + 2x.','Distribute 4 across it: 4x + 8.','Add like terms: x² + 6x + 8.'],'x² + 6x + 8','The constants 4 and 2 add to 6 and multiply to 8. At x = 1, both forms give 15.')],
pitfalls:['Writing (x + 4)² as x² + 16.','Confusing terms joined by addition with factors joined by multiplication.'],engineering:'A geometric area model or simplified relationship may be easier to interpret in factored form and easier to combine in expanded form.',reflection:'Explain what information becomes visible when 6x² + 9x is written as 3x(2x + 3).',quiz:Q('Factor x² − 9 over the real numbers.',['(x − 3)²','(x − 9)(x + 1)','(x − 3)(x + 3)','It cannot be factored'],'c','This is a difference of squares: x² − 3². Multiplying the proposed factors cancels the middle terms.'),sources:[S('e','6-3-multiply-polynomials','multiplying polynomials'),S('e','7-4-factor-special-products','factoring special products')]},
{id:'quadratics-by-factoring',stage:'algebra',order:24,title:'Quadratic equations and the zero-product rule',subtitle:'A squared unknown can have more than one answer.',prerequisites:['polynomials-and-factoring','multistep-linear-equations'],
why:'Quadratics describe many first encounters with nonlinear relationships. Factoring gives a transparent introduction to multiple solutions and contextual restrictions.',
explanation:[
'A quadratic equation has a nonzero squared term as its highest power of the unknown. Put it in the form ax² + bx + c = 0 before using the zero-product property. If a product of real numbers equals zero, at least one factor must be zero. This gives a reason to solve each factor separately after factoring.',
'For (x − 2)(x − 5) = 0, either x = 2 or x = 5. You do not need both factors to vanish simultaneously. Conversely, when a product equals a nonzero number, you cannot set each factor equal to that number and expect a valid rule. Moving everything to one side creates the special zero condition that the method needs.',
'An algebraic root still needs to fit the original question. A length may require a positive answer; a time may be restricted to an interval after a start event. Check all candidate roots in the original equation before applying those contextual restrictions. If a quadratic does not factor conveniently, that does not mean it has no solution. Later methods, including completing the square and the quadratic formula, provide a more general route.'
],worked:[W('Find a rectangle from its area','A rectangle has width x meters and length x + 3 meters. Its area is 28 m².', ['Write x(x + 3) = 28.','Expand and move all terms left: x² + 3x − 28 = 0.','Factor: (x + 7)(x − 4) = 0.','The algebraic roots are x = −7 and x = 4; a physical width must be positive.'],'Width 4 m and length 7 m.','4 × 7 = 28 m². The negative root satisfies the polynomial but does not describe the requested rectangle.')],
pitfalls:['Using the zero-product property before one side is zero.','Discarding a root without explaining whether the reason is algebraic or contextual.'],engineering:'A mathematical model can produce several candidates. Engineering interpretation decides which candidates represent possible situations.',reflection:'Why can a root be algebraically correct but unsuitable as a physical length?',quiz:Q('Solve x² − 5x + 6 = 0.',['Only x = 2','Only x = 3','x = −2 or −3','x = 2 or 3'],'d','The polynomial factors as (x − 2)(x − 3). Either factor can be zero.'),sources:[S('e','7-6-quadratic-equations','quadratic equations by factoring')]}
];

const geometry = [
{id:'angles-and-triangles',stage:'geometry',order:25,title:'Angles, parallel lines, and triangles',subtitle:'A labeled sketch carries relationships.',prerequisites:['equation-balance','signed-numbers'],
why:'Geometry turns verbal descriptions into spatial constraints. You can study this strand alongside algebra rather than waiting for every algebra lesson.',
explanation:[
'An angle describes a turn between two rays sharing a vertex. A full turn is 360°, a straight angle is 180°, and a right angle is 90°. Acute angles are smaller than a right angle; obtuse angles lie between 90° and 180°. An angle does not become larger merely because its drawn rays are longer. The amount of turning is what matters.',
'Adjacent angles forming a straight line sum to 180°. Vertical opposite angles at an intersection are equal. When a transversal crosses parallel lines, corresponding angles and alternate interior angles have useful equality relationships. Mark the parallel-line assumption explicitly; a drawing that merely looks parallel is not a proof that the lines are parallel.',
'In ordinary Euclidean plane geometry, a triangle’s interior angles sum to 180°. This lets a missing angle become an algebra problem. Similar-looking drawings may represent very different sizes, and a sketch need not be to scale. Label known quantities, mark the angle you seek, and write the relationship before solving. Later work on curved surfaces requires different geometry, so keep the flat-plane setting clear.'
],worked:[W('Use a triangle constraint','A triangle has angles x, 2x, and 45°.', ['Their sum is x + 2x + 45 = 180.','Combine and subtract: 3x = 135.','Divide by 3: x = 45.','Thus the three angles are 45°, 90°, and 45°.'],'x = 45°','45 + 90 + 45 = 180, and every angle is positive.')],
pitfalls:['Assuming a diagram is drawn to scale.','Using parallel-line angle rules when parallelism has not been given or justified.'],engineering:'A clear diagram identifies orientations and constraints before numerical work. This habit later supports mechanisms, structures, and coordinate geometry.',reflection:'Explain why extending both rays of a 30° angle does not change the angle.',quiz:Q('Two angles form a straight line. One is 68°. What is the other?',['22°','68°','112°','292°'],'c','Angles on a straight line sum to 180°, so the missing angle is 180 − 68 = 112°.'),sources:[S('p','9-3-use-properties-of-angles-triangles-and-the-pythagorean-theorem','angles and triangles')]},
{id:'perimeter-area',stage:'geometry',order:26,title:'Perimeter, area, and composite shapes',subtitle:'A boundary and the space inside it measure different things.',prerequisites:['units-conversions','variables-expressions'],
why:'Dimensions become meaningful only when you know whether the question concerns an edge, a surface, or an interior. The units help keep those meanings separate.',
explanation:[
'Perimeter measures the total length around a boundary. Area measures how much two-dimensional space is covered, using square units. A rectangle of width w and length l has perimeter 2l + 2w and area lw. The formulas answer different questions even though they use the same dimensions. Drawing a grid of unit squares explains why the area multiplies the two lengths.',
'A triangle has area one half times a chosen base times its perpendicular height. The height is the distance straight across from the opposite vertex to the base line, not necessarily a sloping side. A parallelogram uses base times perpendicular height because its area can be rearranged into a rectangle. A trapezoid uses the average of its parallel base lengths times the perpendicular height.',
'Break a composite shape into nonoverlapping familiar pieces, or subtract a missing piece from a larger enclosing shape. State what is included. A hole removes covered area but may add an inner boundary if the question asks for all exposed edges. For perimeter, trace the actual outside boundary and count only the requested edges. Two shapes with equal area need not have equal perimeter.'
],worked:[W('Subtract a rectangular opening','A 10 cm by 8 cm plate contains a 4 cm by 3 cm rectangular opening fully inside it.', ['Outer area is 10 × 8 = 80 cm².','Opening area is 4 × 3 = 12 cm².','Remaining covered area is 80 − 12 = 68 cm².','The outer boundary alone has length 2(10 + 8) = 36 cm.'],'Area 68 cm²; outer perimeter 36 cm.','The remaining area is smaller than 80 cm² and positive. Including the hole boundary would add 14 cm, giving 50 cm of total boundary.')],
pitfalls:['Using a sloping side instead of perpendicular height in a triangle-area formula.','Confusing the outer perimeter with all boundaries around a perforated shape.'],engineering:'Surface coverage and edge treatment require different measurements. A diagram makes the accounting boundary explicit.',reflection:'Can two rectangles have area 24 cm² but different perimeters? Construct an example.',quiz:Q('A triangle has base 12 m and perpendicular height 5 m. Its area is:',['60 m²','30 m²','17 m²','34 m²'],'b','Area = (1/2)(12)(5) = 30 m². The height must be perpendicular to the base.'),sources:[S('p','9-4-use-properties-of-rectangles-triangles-and-trapezoids','areas and perimeters')]},
{id:'right-triangle-distance',stage:'geometry',order:27,title:'Pythagoras and coordinate distance',subtitle:'Perpendicular components combine through their squares.',prerequisites:['angles-and-triangles','powers-roots-scientific','coordinates-and-slope'],
why:'Right-triangle geometry links a pair of coordinates to an actual distance. The same structure later gives the magnitude of a vector.',
explanation:[
'For a right triangle with perpendicular legs a and b and hypotenuse c, the Pythagorean theorem says a² + b² = c². The hypotenuse lies opposite the right angle and is the longest side. Identify it before substituting. If you know the hypotenuse and one leg, rearrange the relation rather than blindly adding the two known squares.',
'Between coordinate points (x₁, y₁) and (x₂, y₂), horizontal and vertical differences form perpendicular legs. Their straight-line distance is √[(x₂ − x₁)² + (y₂ − y₁)²]. The differences may be signed, but their squares contribute nonnegative amounts. This distance differs from the length of a route that follows the two coordinate directions separately.',
'The theorem requires a right angle and compatible length units. A diagonal across an ordinary rectangular surface is a suitable example. An arbitrary triangle needs a different method, and a long route on a curved planetary surface is not automatically represented by a flat-plane triangle. Keep an exact root when useful; a rounded decimal should indicate the precision appropriate to the problem.'
],worked:[W('Find a straight-line reach','A target is at (−2, 1) m and a starting point at (4, 9) m in a plane.', ['Horizontal difference is 4 − (−2) = 6 m.','Vertical difference is 9 − 1 = 8 m.','Distance is √(6² + 8²) = √100.'],'10 m','The result exceeds either individual component but is less than the 6 + 8 = 14 m two-leg route.')],
pitfalls:['Using the theorem on a triangle without a justified right angle.','Adding coordinate values instead of finding their differences.'],engineering:'Planar position errors and rectangular clearances often reduce to perpendicular distances. Coordinate definitions and units determine whether the calculation applies.',reflection:'Why is the straight-line distance no greater than traveling along both legs in this example?',quiz:Q('A right triangle has hypotenuse 13 and one leg 5. What is the other leg?',['8','12','18','√194'],'b','The missing square is 13² − 5² = 169 − 25 = 144, whose positive square root is 12.'),sources:[S('p','9-3-use-properties-of-angles-triangles-and-the-pythagorean-theorem','the Pythagorean theorem')]},
{id:'similarity-and-scale',stage:'geometry',order:28,title:'Similarity and scale drawings',subtitle:'Preserve shape while changing size.',prerequisites:['angles-and-triangles','proportions-percent-change'],
why:'Similarity turns a measured small drawing into information about a larger shape. It also explains why trigonometric ratios can depend on angle alone.',
explanation:[
'Similar figures have corresponding angles equal and corresponding lengths in one common ratio. Congruent figures have the same shape and size; similarity allows a size change. Label corresponding vertices before setting up a proportion. The shortest side of one triangle should not be paired with an unrelated side of the other simply because both labels are nearby on the page.',
'A scale of 1:25 means one model length unit represents twenty-five of the same real length units. Convert units if the model uses centimeters and the real dimension is requested in meters. The length multiplier applies uniformly to every corresponding length. It does not directly apply to area or volume, because those quantities involve two or three multiplied lengths.',
'For triangles, two equal corresponding angles force the third angle to agree, establishing similar shape. This can justify indirect measurement when the geometric assumptions hold. For example, shadow methods require comparable illumination and an appropriate ground model. A physical scale model may preserve shape while failing to preserve other behavior; similarity in geometry alone does not guarantee similarity in airflow, strength, or thermal performance.'
],worked:[W('Interpret a mechanical drawing','A drawing is at 1:40 scale. A represented beam measures 7.5 cm on the page.', ['Use the length scale: real length = 7.5 × 40 = 300 cm.','Convert centimeters to meters: 300/100 = 3.','Keep the scale ratio attached to lengths, not areas.'],'3 m','A 3 m beam is 300 cm, and shrinking it by 40 returns 7.5 cm.')],
pitfalls:['Comparing a model length in centimeters directly with a real length in meters without converting.','Assuming that a length scale is also an area or volume scale.'],engineering:'Drawings and geometric models preserve dimensions through stated scales. Predicting physical performance requires additional models and experiments.',reflection:'Why is a geometrically similar miniature not automatically a valid test of full-size structural behavior?',quiz:Q('A 1:20 drawing shows a 9 cm length. What real length does it represent?',['0.45 m','1.8 m','18 m','180 m'],'b','9 × 20 = 180 cm, which is 1.8 m.'),sources:[S('p','9-3-use-properties-of-angles-triangles-and-the-pythagorean-theorem','similar triangles')]},
{id:'circles-and-arcs',stage:'geometry',order:29,title:'Circles, circumference, and sectors',subtitle:'Separate radius, boundary length, and covered area.',prerequisites:['perimeter-area','ratios-rates-percents'],
why:'Wheels, circular openings, and rotational geometry connect linear distance with a turn. Circle formulas prepare you for radians and trigonometry.',
explanation:[
'A circle consists of points at a fixed distance, the radius r, from a center. The diameter passes through the center and has length 2r. Circumference is the boundary length, C = 2πr. The enclosed disk has area A = πr². Pi is a fixed irrational number, so formulas containing π can be exact even when their decimal evaluations are approximate.',
'A central angle selects a fraction of the full circle. In degrees, an angle θ represents θ/360 of a full turn. Its arc length is that fraction of the circumference, and its sector area is that fraction of the disk area. An arc follows the curved boundary; a chord joins its endpoints with a straight segment. These are different lengths.',
'For a ring-shaped region, subtract the inner disk area from the outer disk area. Keep radii consistent and convert diameter to radius before squaring. A wheel’s rolling distance equals circumference times rotations only under an ideal no-slip assumption. Real measurements can differ because the effective rolling radius, surface contact, and slip affect the relationship.'
],worked:[W('Measure a quarter-circle section','A circle has radius 6 cm. Find the arc length and sector area for a 90° central angle.', ['The angle is 90/360 = 1/4 of a turn.','Full circumference is 12π cm, so the arc is 3π cm.','Full area is 36π cm², so the sector area is 9π cm².'],'Arc: 3π cm; sector area: 9π cm².','Four identical sectors reconstruct the whole circumference and disk area.')],
pitfalls:['Substituting a diameter where a radius is required.','Confusing a curved arc length with its straight chord.'],engineering:'Rotating mechanisms and circular geometry require careful distinctions between angle, distance around a boundary, and area.',reflection:'If radius doubles, what happens to circumference and area? Explain from the formulas.',quiz:Q('A disk has diameter 10 cm. What is its area?',['10π cm²','20π cm²','25π cm²','100π cm²'],'c','Its radius is 5 cm, so area is π(5²) = 25π cm².'),sources:[S('p','9-5-solve-geometry-applications-circles-and-irregular-figures','circles and irregular figures')]},
{id:'volume-surface-area',stage:'geometry',order:30,title:'Volume and surface area',subtitle:'Space inside and material around it are different quantities.',prerequisites:['perimeter-area','circles-and-arcs','units-conversions'],
why:'Packaging, containers, and simple habitat models require three-dimensional reasoning. Cubic and square units identify which question you are answering.',
explanation:[
'Volume measures three-dimensional space in cubic units. A rectangular box has volume length × width × height. A right circular cylinder has volume base area × height, or πr²h. Imagine stacking many identical thin layers: each layer contributes area times thickness, and the total thickness becomes the height. This picture helps connect familiar area to a new dimension.',
'Surface area adds the areas of the exposed faces. A closed rectangular box has two faces of each size, giving 2(lw + lh + wh). A closed cylinder has two circular ends plus its curved side, giving 2πr² + 2πrh. If a container is open, omit the missing face. Read the geometry and what counts as exposed rather than choosing a formula solely from a shape name.',
'Interior volume is not automatically material volume. A hollow container may have a large capacity but little wall material; estimating its mass requires the material volume and density, with geometry and thickness assumptions stated. Convert cubic units by cubing a length conversion. Because 1 m = 100 cm, one cubic meter contains 1,000,000 cubic centimeters, not one hundred.'
],worked:[W('Distinguish capacity and coverage','A closed rectangular teaching model measures 3 m by 2 m by 1 m.', ['Volume = 3 × 2 × 1 = 6 m³.','The three distinct face areas are 6, 3, and 2 m².','Each occurs twice, so surface area = 2(6 + 3 + 2) = 22 m².'],'Volume 6 m³; surface area 22 m².','Six unit cubes fill the ideal interior. Counting each of the six rectangular faces separately gives the same 22 m².')],
pitfalls:['Using interior volume times material density for a hollow object.','Forgetting that a missing lid changes surface area but not the nominal interior volume formula.'],engineering:'Container capacity, surface treatment, and material mass need different geometric inputs. Naming the quantity prevents a correct formula from answering the wrong question.',reflection:'For an open rectangular tray, which face would you remove from the closed-box surface-area calculation?',quiz:Q('A cylinder has radius 2 m and height 5 m. What is its volume?',['10π m³','20π m³','25π m³','40π m³'],'b','Volume = πr²h = π(2²)(5) = 20π m³.'),sources:[S('p','9-6-solve-geometry-applications-volume-and-surface-area','volume and surface area')]},
{id:'geometric-scaling',stage:'geometry',order:31,title:'Length, area, and volume scaling',subtitle:'Bigger changes the balance between surface and interior.',prerequisites:['similarity-and-scale','volume-surface-area'],
why:'Scaling reveals why enlarging a design affects different requirements at different rates. The argument begins with basic powers rather than advanced physics.',
explanation:[
'Suppose every corresponding length in a shape is multiplied by a positive scale factor k. A length changes by k. An area combines two lengths, so it changes by k². A volume combines three, so it changes by k³. This reasoning applies to geometrically similar shapes regardless of whether they are boxes, cylinders, or more complicated forms.',
'The surface-area-to-volume ratio therefore changes by k²/k³ = 1/k. A larger similar shape has less surface area per unit interior volume. The ratio carries inverse-length units, such as m⁻¹; it is not unitless. Compare ratios only after choosing compatible units. The geometric result can guide questions about boundaries and interiors, but it does not alone predict heat transfer or structural strength.',
'Mass scales with volume only under stated conditions, such as the same homogeneous material filling geometrically similar solid objects. A thin shell with unchanged wall thickness has a different relationship, and a redesigned structure may change thickness, materials, and internal layout. Use the simplest justified scaling model, then identify where it stops representing the actual object.'
],worked:[W('Enlarge a cubic enclosure','Compare cubes with sides 2 m and 6 m.', ['The length factor is k = 6/2 = 3.','Surface area changes by 3² = 9; volume changes by 3³ = 27.','The smaller cube has area 24 m² and volume 8 m³, ratio 3 m⁻¹.','The larger cube has area 216 m² and volume 216 m³, ratio 1 m⁻¹.'],'Area ×9, volume ×27, surface-to-volume ratio divided by 3.','Direct calculations agree with the scale-factor predictions.')],
pitfalls:['Calling an object “twice as big” without saying whether you mean length, area, or volume.','Assuming every component of an engineered assembly follows the same mass scaling rule.'],engineering:'A habitat or robot can preserve its overall shape while changing the balance of packaging and exposed surface. Geometry suggests questions that detailed engineering must answer.',reflection:'If every length is halved, what happens to surface area per unit volume?',quiz:Q('Every length is multiplied by 4. By what factor does volume increase?',['4','8','16','64'],'d','Three length factors contribute: 4³ = 64.'),sources:[S('p','9-6-solve-geometry-applications-volume-and-surface-area','three-dimensional geometry'),S('c','1-5-transformation-of-functions','scaling relationships')]},
{id:'right-triangle-ratios',stage:'geometry',order:32,title:'An introduction to right-triangle ratios',subtitle:'Angle determines a ratio before it determines a length.',prerequisites:['right-triangle-distance','similarity-and-scale'],
why:'Trigonometry connects direction and distance. This is a bridge lesson; the full circle and function viewpoint arrive later in precalculus.',
explanation:[
'Choose one acute angle in a right triangle. Relative to that chosen angle, identify the opposite leg, adjacent leg, and hypotenuse. The hypotenuse is always opposite the right angle, but the opposite and adjacent legs switch roles when you choose the other acute angle. Label the chosen angle before writing any ratio.',
'Sine is opposite divided by hypotenuse; cosine is adjacent divided by hypotenuse; tangent is opposite divided by adjacent. Similar right triangles with the same acute angle have the same side ratios. That is why these quantities depend on angle rather than the size of the drawing. A ratio can be known exactly from side lengths even before you can calculate the angle itself.',
'If you know an angle and one side, a suitable ratio can find another side. If you know two sides and seek an angle, an inverse trigonometric function may be used later. Check the calculator mode when angles are given in degrees; radians are another unit introduced in precalculus. For now, focus on naming sides and deciding which ratio connects the quantities you actually know.'
],worked:[W('Read ratios from a triangle','A right triangle has legs 5 and 12 and hypotenuse 13. Choose the angle opposite the leg of length 5.', ['The opposite leg is 5 and the adjacent leg is 12.','Therefore sin θ = 5/13 and cos θ = 12/13.','Tangent is tan θ = 5/12.'],'sin θ = 5/13, cos θ = 12/13, tan θ = 5/12.','The sine and cosine ratios are below one because each leg is shorter than the hypotenuse.')],
pitfalls:['Choosing opposite and adjacent sides before selecting the reference angle.','Applying these simple side definitions to a triangle that is not right-angled.'],engineering:'A robot arm’s reach in horizontal and vertical directions can be described through right-triangle ratios under a planar geometric model.',reflection:'How do the sine and cosine ratios change when you select the other acute angle of the same triangle?',quiz:Q('Relative to an acute angle, opposite = 8 and adjacent = 15. What is tangent?',['8/17','15/17','8/15','15/8'],'c','Tangent compares opposite to adjacent, so it is 8/15. The hypotenuse is not needed for this ratio.'),sources:[S('c','5-4-right-triangle-trigonometry','right-triangle trigonometry')]}
];

const algebra2 = [
{id:'functions-domain-range',stage:'algebra2',order:33,title:'Functions, domain, and range',subtitle:'One allowed input produces one output.',prerequisites:['linear-models','powers-roots-scientific'],
why:'Functions provide the main language of precalculus and calculus. Understanding their inputs, outputs, and restrictions matters more than merely evaluating a formula.',
explanation:[
'A function assigns exactly one output to each allowed input. Several inputs may share an output: both 2 and −2 produce 4 under squaring. What is forbidden is one input producing two different outputs under the same function definition. The notation f(x) names the output at x; it does not mean f multiplied by x. A table, graph, formula, or verbal rule can describe a function.',
'The domain is the allowed input set. The range is the set of outputs actually produced. Algebraic restrictions include avoiding zero denominators and, for real-valued square-root formulas, keeping the radicand nonnegative. Physical restrictions may be narrower: a duration could be limited to 0 through 10 seconds even if the formula accepts all real inputs. State whether you are discussing the mathematical domain or the model’s intended domain.',
'Piecewise definitions apply different rules over different input intervals. Select the interval before calculating; do not add all the formulas together. At a shared boundary, the definition must specify which rule includes the point. On a graph, a vertical line can intersect a function graph at most once. That test expresses the one-output condition visually, but it does not tell you whether the model describes a real process accurately.'
],worked:[W('Read a square-root function','Let f(x) = √(x − 2), with real inputs and outputs.', ['Require x − 2 ≥ 0, so x ≥ 2.','At x = 11, f(11) = √9 = 3.','The principal square root is nonnegative, so every output is at least zero.','Every nonnegative output y is reached by choosing x = y² + 2.'],'Domain: x ≥ 2. Range: y ≥ 0. f(11) = 3.','The chosen input 11 belongs to the domain, and 3² + 2 returns 11.')],
pitfalls:['Calling all real numbers the domain without inspecting the formula.','Assuming a function must assign different outputs to different inputs.'],engineering:'A sensor model connects an input to an output within a defined operating range. Mathematical and physical restrictions both belong in its description.',reflection:'Why is y = x² a function even though two different inputs can produce the same output?',quiz:Q('Which input is excluded from g(x) = 1/(x + 4)?',['0','4','−4','1'],'c','At x = −4 the denominator is zero, making the expression undefined.'),sources:[S('c','1-1-functions-and-function-notation','functions'),S('c','1-2-domain-and-range','domain and range')]},
{id:'quadratic-forms-formula',stage:'algebra2',order:34,title:'Quadratic forms and the quadratic formula',subtitle:'Choose a form that reveals the feature you need.',prerequisites:['quadratics-by-factoring','functions-domain-range'],
why:'Factoring is only one tool for quadratics. Vertex form exposes a turning point, while the quadratic formula handles cases with inconvenient roots.',
explanation:[
'The standard form ax² + bx + c shows coefficients. Factored form, when available, exposes roots. Vertex form a(x − h)² + k identifies a vertex at (h, k) and axis of symmetry x = h. For positive a the vertex is a minimum; for negative a it is a maximum. These forms can represent the same function while making different questions easier.',
'Completing the square reorganizes a quadratic using a perfect-square expression. For x² − 6x + 5, add and subtract 9 to obtain (x − 3)² − 4. The added and subtracted quantities cancel, so the value has not changed. This procedure also leads to the quadratic formula: for ax² + bx + c = 0 with a ≠ 0, x = [−b ± √(b² − 4ac)]/(2a). The whole numerator is divided by 2a.',
'The discriminant b² − 4ac indicates the real-root situation: positive gives two distinct real roots, zero gives one repeated real root, and negative gives no real roots. A negative discriminant will be meaningful in the complex-number system later. Whatever method you choose, verify the candidates and apply any physical domain restrictions after the algebra.'
],worked:[W('Read a vertex and find roots','Analyze f(x) = x² − 6x + 5.', ['Complete the square: f(x) = (x − 3)² − 4.','The minimum is −4 at x = 3.','For roots, (x − 3)² = 4 gives x − 3 = ±2.','Thus x = 1 or x = 5.'],'Vertex (3, −4); real roots 1 and 5.','Substitution gives f(1) = 0 and f(5) = 0; the roots are equally spaced around x = 3.')],
pitfalls:['Forgetting the ± when solving a squared equation.','Dividing only the square-root term by 2a in the quadratic formula.'],engineering:'Turning points matter when a valid quadratic model describes a quantity to minimize or maximize. The model’s allowed interval may limit which point is relevant.',reflection:'Which form would you choose to read roots quickly, and which to read a maximum or minimum?',quiz:Q('What is the vertex of y = 2(x + 1)² − 7?',['(1, −7)','(−1, −7)','(−1, 7)','(2, −7)'],'b','The squared term becomes zero at x = −1; the corresponding output is −7.'),sources:[S('i','9-3-solve-quadratic-equations-using-the-quadratic-formula','the quadratic formula'),S('i','9-6-graph-quadratic-functions-using-properties','quadratic graphs')]},
{id:'rational-expressions',stage:'algebra2',order:35,title:'Rational expressions and restrictions',subtitle:'Cancel factors while keeping the original domain.',prerequisites:['polynomials-and-factoring','functions-domain-range'],
why:'Algebraic fractions appear throughout later mathematics. Reliable simplification depends on factoring, fraction logic, and careful handling of excluded inputs.',
explanation:[
'A rational expression is a quotient of polynomials with a nonzero denominator. Before simplifying, identify values that make the original denominator zero. These are excluded even if a later cancellation removes the visible denominator. A simpler expression may match the original wherever the original is defined without having exactly the same natural domain.',
'Cancellation divides a whole numerator and denominator by a shared nonzero factor. Factor first so those whole factors are visible. In (x² − 9)/(x − 3), the numerator is (x − 3)(x + 3), so cancellation gives x + 3 for x ≠ 3. By contrast, the x in (x + 3)/x is only one term of a sum, not a factor of the complete numerator. It cannot simply be canceled.',
'Multiplication and division follow the same fraction rules you already know, with extra restrictions whenever a divisor might be zero. Addition requires a common denominator; preserve each whole numerator in parentheses while combining. The goal is an equivalent expression on the correct domain, not merely the shortest-looking line. Numerical substitution at allowed inputs can expose an invalid cancellation.'
],worked:[W('Simplify without restoring an excluded input','Simplify (x² − 16)/(x − 4).', ['The original denominator requires x ≠ 4.','Factor the numerator: x² − 16 = (x − 4)(x + 4).','Cancel the common factor only where it is nonzero.'],'x + 4, with x ≠ 4.','At x = 6 the original is 20/2 = 10 and the simplified form is 10. At x = 4 the original remains undefined.')],
pitfalls:['Canceling terms separated by addition.','Forgetting an excluded value after its factor disappears from the simplified formula.'],engineering:'A simplified model must retain its operating and mathematical restrictions. Removing notation does not remove the original limitation.',reflection:'Why do the formulas (x² − 16)/(x − 4) and x + 4 differ when their domains are not stated?',quiz:Q('Simplify (3x + 6)/3.',['x + 6','x + 2','3x + 2','x/3 + 2'],'b','Factor the numerator as 3(x + 2), then divide the whole numerator by 3.'),sources:[S('i','7-1-multiply-and-divide-rational-expressions','rational expressions'),S('i','7-2-add-and-subtract-rational-expressions','adding rational expressions')]},
{id:'rational-equations-rates',stage:'algebra2',order:36,title:'Rational equations and combined rates',subtitle:'Clear denominators without losing the conditions.',prerequisites:['rational-expressions','systems-of-equations'],
why:'Unknowns can appear in denominators when time, speed, and rates interact. The algebra works only on the domain of the original equation.',
explanation:[
'Start a rational equation by recording all excluded inputs. Then multiply every term by a common denominator to obtain a more manageable equation. This multiplication is reversible only where that denominator is nonzero. Solve the resulting equation, but treat its solutions as candidates until each has been checked in the original.',
'Combined work problems add rates, not completion times. If one pump fills one idealized tank in four hours, its rate is one quarter tank per hour. A second taking twelve hours contributes one twelfth tank per hour. Under constant independent operation, their rates add. The reciprocal of the total rate gives the time for one whole tank. Units explain why adding four and twelve hours is not the right operation.',
'A rate model needs assumptions: constant flow, no leakage, compatible quantities, and no interaction that changes individual rates. A real system may violate these. The mathematics tells you what follows if the assumptions are true; observations tell you whether the assumptions are useful. Keep an algebraic domain restriction separate from a physical one, such as requiring time to be positive.'
],worked:[W('Solve a rational equation','Solve (x + 1)/(x − 2) = 3.', ['Exclude x = 2.','Multiply by x − 2: x + 1 = 3x − 6.','Rearrange to 7 = 2x.'],'x = 7/2','At x = 3.5, the original quotient is 4.5/1.5 = 3.'),W('Combine two constant rates','Two independent ideal pumps fill a tank in 4 h and 12 h individually.', ['Combined rate is 1/4 + 1/12 = 1/3 tank/h.','Time for one tank is 1 ÷ (1/3) = 3 h.'],'3 hours under the stated assumptions.','The result is shorter than either individual filling time.')],
pitfalls:['Keeping a candidate that makes an original denominator zero.','Adding task durations when the quantities that combine are rates.'],engineering:'Flow and timing estimates often begin with reciprocal relationships. Real interactions and operating limits must be checked separately.',reflection:'Why should two positive independent filling rates produce a shorter filling time than either alone?',quiz:Q('Solve 6/(x − 1) = 2, with the original denominator nonzero.',['2','3','4','5'],'c','Multiplication gives 6 = 2(x − 1), so x = 4. The denominator is then 3, which is allowed.'),sources:[S('i','7-4-solve-rational-equations','rational equations')]},
{id:'radicals-rational-powers',stage:'algebra2',order:37,title:'Radicals and rational exponents',subtitle:'Undo powers while respecting sign and domain.',prerequisites:['powers-roots-scientific','quadratic-forms-formula'],
why:'Roots appear in distance, scaling, and equation solving. Rational exponents connect them to the exponent rules used throughout precalculus.',
explanation:[
'For positive real a, a^(1/n) denotes the positive nth root, and a^(m/n) combines a root with an integer power. Thus 16^(3/4) means the cube of the fourth root of 16. Restricting this introductory rule to positive bases avoids the extra domain details that arise for negative bases and different root types. Odd roots of negative numbers can be real; even roots are not real there.',
'Simplify square roots by extracting perfect-square factors: √72 = √(36 × 2) = 6√2. Like radicals combine by adding their coefficients, so 3√2 + 5√2 = 8√2. But √(a + b) generally does not equal √a + √b. Also √(x²) = |x| for real x, because the principal square root is nonnegative even when x is negative.',
'When solving an equation containing a square root, isolate the root before squaring. Squaring both sides may introduce candidates that do not satisfy the original equation, because opposite values have equal squares. Check every candidate afterward. Pay attention to the original root’s domain and sign: a real principal square root cannot equal a negative number.'
],worked:[W('Check a radical-equation candidate','Solve √(x + 5) = x − 1 over the real numbers.', ['The right side must be nonnegative, so x ≥ 1.','Square both sides: x + 5 = x² − 2x + 1.','Rearrange: x² − 3x − 4 = (x − 4)(x + 1) = 0.','Candidates are 4 and −1; only 4 meets the original equation.'],'x = 4','At 4, √9 = 3 = 4 − 1. At −1, √4 = 2 but the right side is −2, so reject it.')],
pitfalls:['Distributing a square root across addition.','Assuming that squaring preserves the exact solution set without a final check.'],engineering:'Distance and scaling models often contain roots. Choosing a physical branch and retaining domain restrictions are part of interpreting a solution.',reflection:'Why is √(x²) equal to |x| rather than x for every real x?',quiz:Q('What is 27^(2/3)?',['3','6','9','18'],'c','The cube root of 27 is 3, and squaring it gives 9.'),sources:[S('i','8-1-simplify-expressions-with-roots','roots'),S('i','8-3-simplify-rational-exponents','rational exponents'),S('i','8-6-solve-radical-equations','radical equations')]},
{id:'exponential-change',stage:'algebra2',order:38,title:'Exponential growth and decay',subtitle:'A constant percentage is a changing amount.',prerequisites:['proportions-percent-change','functions-domain-range'],
why:'Repeated multiplicative change produces patterns that a straight line cannot capture. Recognizing the pattern prevents misleading long-term estimates.',
explanation:[
'A linear sequence adds the same amount each step. An exponential sequence multiplies by the same factor. In A(n) = A₀bⁿ, A₀ is the initial amount, n counts equal intervals, and b is the multiplier per interval. For positive A₀, a factor above one gives growth; a factor between zero and one gives decay. The exponent is the input, unlike a quadratic where the input is the base being squared.',
'A 12% increase per interval uses b = 1.12. A 12% decrease uses b = 0.88. The amount added or removed changes because the percentage acts on a new current amount each time. Half-life and doubling-time descriptions are special cases of repeated factors. A table can expose the pattern by comparing successive ratios instead of successive differences.',
'The time unit belongs to the model. A monthly factor cannot be applied once per year without conversion. A simple discrete model also does not automatically describe what happens between update times. Real processes may depart from constant proportional change as conditions evolve. Use an exponential relationship when the mechanism or data justifies it, and state the interval over which you intend to trust it.'
],worked:[W('Track repeated retained fractions','A hypothetical quantity starts at 160 units and retains 75% after each cycle.', ['The retention factor is 0.75, so A(n) = 160(0.75)ⁿ.','After one cycle: 120. After two: 90.','After three: 67.5.'],'67.5 units after three cycles.','Each successive ratio is 0.75. The removed amounts 40, 30, and 22.5 are not constant.')],
pitfalls:['Subtracting the same number of units for every percentage decrease.','Using a growth factor for the wrong time interval.'],engineering:'Some simplified decay and response models are exponential. Choosing the model requires evidence; learning its mathematics does not assert that every system follows it.',reflection:'What table pattern would distinguish constant additive change from constant proportional change?',quiz:Q('A quantity starts at 50 and triples each cycle. What is it after two cycles?',['150','300','450','900'],'c','Two cycles multiply by 3 twice: 50 × 3² = 450.'),sources:[S('i','10-2-evaluate-and-graph-exponential-functions','exponential functions')]},
{id:'logarithms-introduction',stage:'algebra2',order:39,title:'Logarithms ask for the exponent',subtitle:'Reverse an exponential relationship.',prerequisites:['exponential-change','radicals-rational-powers'],
why:'When an unknown appears in an exponent, ordinary division cannot isolate it. A logarithm names exactly the missing exponent.',
explanation:[
'The statement log_b(a) = c means bᶜ = a. For real logarithms, the base b is positive and not one, and the argument a is positive. For example, log₂(32) = 5 because five factors of two produce 32. A logarithm can be negative: log₁₀(0.01) = −2 because 10⁻² = 0.01. A negative output is not the same as a negative argument.',
'Logarithm rules reflect exponent rules. For positive M and N, log_b(MN) = log_b M + log_b N and log_b(M/N) = log_b M − log_b N. The power rule brings a valid exponent down as a multiplier. There is no corresponding rule that splits log(M + N) into a sum of logarithms. Test that false idea using small powers of ten if you need a memorable counterexample.',
'The common logarithm uses base ten; the natural logarithm ln uses the constant e as its base. You do not need to know every application of e yet. On a calculator, change of base gives log_b(a) = ln(a)/ln(b). Keep the complete arguments grouped, and check the result by returning to the original exponential form rather than trusting an unfamiliar decimal alone.'
],worked:[W('Count repeated doublings','Solve 40 × 2ⁿ = 640.', ['Divide both sides by 40 to get 2ⁿ = 16.','Ask which exponent on 2 produces 16.','Since 2⁴ = 16, n = log₂(16) = 4.'],'4 doublings','40 × 16 = 640; the original equation is satisfied.')],
pitfalls:['Confusing a negative logarithm value with an invalid negative argument.','Splitting a logarithm of a sum using the product rule.'],engineering:'Logarithmic scales compare quantities spanning wide ranges. In physical applications, logarithms typically act on dimensionless quantities or ratios.',reflection:'Explain why log_b(1) is zero for every allowed base b.',quiz:Q('What is log₁₀(0.001)?',['−3','3','−1,000','0.001'],'a','10⁻³ = 0.001, so the exponent requested is −3.'),sources:[S('c','4-3-logarithmic-functions','logarithmic functions'),S('c','4-5-logarithmic-properties','logarithm rules')]},
{id:'complex-numbers',stage:'algebra2',order:40,title:'A first look at complex numbers',subtitle:'Extend the number system without discarding algebra.',prerequisites:['quadratic-forms-formula','polynomials-and-factoring'],
why:'Some polynomial equations have no real solution. Complex numbers extend the system and become useful later in mathematical descriptions of oscillation and signals.',
explanation:[
'No real number squares to −1. Define a new number i by i² = −1. A complex number has the form a + bi, with real numbers a and b. The real numbers are included as the special case b = 0. The word imaginary is a historical label; it does not mean the mathematics is arbitrary or that the number should be ignored.',
'Add and subtract by combining real parts and imaginary coefficients separately. Multiply by distributing just as with polynomials, then replace i² with −1. Powers of i repeat in a cycle: i, −1, −i, 1. The conjugate of a + bi is a − bi; their product is a² + b², a real nonnegative quantity. That relationship also helps when dividing complex numbers.',
'A complex number can be represented by a point in a plane with real and imaginary axes. Its magnitude is √(a² + b²), echoing the distance formula. Do not impose the ordinary real-number ordering on all complex numbers; statements such as one complex number being greater than another have no single standard meaning. This lesson introduces notation and arithmetic, not a requirement to master advanced applications before beginning college.'
],worked:[W('Multiply and simplify','Compute (2 + 3i)(1 − 2i).', ['Distribute: 2 − 4i + 3i − 6i².','Replace i² with −1, so −6i² becomes +6.','Combine real and imaginary parts.'],'8 − i','The real contribution is 2 + 6 = 8, and the imaginary coefficient is −4 + 3 = −1.')],
pitfalls:['Treating i² as +1.','Concluding that an equation has no solutions of any kind because it has no real solutions.'],engineering:'Complex numbers provide compact tools in later signals and vibration mathematics. Their practical value grows after you understand functions and trigonometry.',reflection:'Why are real numbers still part of the complex-number system?',quiz:Q('What are the complex solutions of x² + 9 = 0?',['x = ±3','x = ±9i','x = ±3i','Only x = 3i'],'c','x² must equal −9. Both 3i and −3i square to −9.'),sources:[S('i','8-8-use-the-complex-number-system','complex numbers')]}
];

const precalculus = [
{id:'transform-compose-invert',stage:'precalculus',order:41,title:'Transform, compose, and invert functions',subtitle:'Trace what happens to the input and then the output.',prerequisites:['functions-domain-range','quadratic-forms-formula'],
why:'Precalculus studies relationships between functions, not just isolated formulas. These operations help describe calibration chains and build complicated models from understandable parts.',
explanation:[
'A transformation changes a function’s graph in a controlled way. In g(x) = a f(x − h) + k, the subtraction inside shifts the graph right by h, the outside multiplier scales outputs by a, and the outside addition shifts outputs by k. A negative a reflects outputs across the horizontal axis. Check a familiar point to understand the apparently reversed sign of a horizontal shift.',
'Composition feeds one function’s output into another: (f ∘ g)(x) = f(g(x)). Evaluate the inner function first. Order matters; f(g(x)) and g(f(x)) generally differ. The input must belong to the inner function’s domain, and the resulting value must belong to the outer function’s domain. A chain of formulas is not valid merely because each formula works somewhere.',
'An inverse function reverses an original function on an appropriate domain. The original must assign distinct outputs to distinct allowed inputs. For example, squaring on all real numbers is not one-to-one, but restricting inputs to x ≥ 0 allows the inverse square root. The notation f⁻¹ means inverse function, not reciprocal 1/f. Verify an inverse by composing in both directions on the stated domains.'
],worked:[W('Reverse a simple calibration','Let f(x) = 3x − 2.', ['Write y = 3x − 2 and solve for x.','Add 2 and divide by 3: x = (y + 2)/3.','Rename the inverse input: f⁻¹(x) = (x + 2)/3.'],'f⁻¹(x) = (x + 2)/3','f⁻¹(f(x)) = (3x − 2 + 2)/3 = x; f(f⁻¹(x)) = 3(x + 2)/3 − 2 = x.')],
pitfalls:['Reading inverse-function notation as a reciprocal.','Ignoring the intermediate domain when composing functions.'],engineering:'A measurement may pass through several conversion and calibration steps. Composition describes the chain; an inverse may recover an input when information has not been lost.',reflection:'Why does squaring require a domain restriction before its inverse can be a function?',quiz:Q('If f(x) = x + 4 and g(x) = 2x, what is f(g(3))?',['10','14','11','7'],'a','First g(3) = 6, then f(6) = 10. Reversing the order would give a different result.'),sources:[S('c','1-4-composition-of-functions','composition'),S('c','1-5-transformation-of-functions','transformations'),S('c','1-7-inverse-functions','inverse functions')]},
{id:'polynomial-rational-graphs',stage:'precalculus',order:42,title:'Read polynomial and rational graphs',subtitle:'Connect algebraic structure with shape and boundaries.',prerequisites:['rational-expressions','quadratic-forms-formula','transform-compose-invert'],
why:'A graph should be explainable from its formula. Zeros, end behavior, holes, and asymptotes provide landmarks before you ask software to draw a curve.',
explanation:[
'For a polynomial, roots identify horizontal-axis intersections. A factor raised to an odd multiplicity generally crosses the axis at that root, while even multiplicity touches and turns there. The leading term controls the eventual direction of the graph as input becomes very large in magnitude. Lower-degree terms still matter near ordinary inputs and can change the local shape substantially.',
'Rational functions require inspection of the original denominator. A canceled factor can create a missing point, or hole, rather than a vertical asymptote. A remaining denominator zero may produce a vertical asymptote after all common factors are removed. Study behavior on each side instead of placing a filled point where the original formula is undefined.',
'An asymptote describes limiting behavior, not a universal wall that a graph can never cross. Horizontal asymptotes concern large-magnitude inputs; a rational graph may cross one at a finite input. For a quotient of polynomials of equal degree, the leading-coefficient ratio gives the horizontal asymptote. Graphing software is a useful check, but its plotting window and sampling can hide holes or misleadingly connect across a discontinuity.'
],worked:[W('Distinguish a hole from an asymptote','Analyze f(x) = (x² − 1)/(x − 1).', ['Exclude x = 1 from the original domain.','Factor the numerator as (x − 1)(x + 1).','For x ≠ 1, the graph follows y = x + 1.','At x = 1 the corresponding line height would be 2, but the original function has no value there.'],'The line y = x + 1 with a hole at (1, 2).','Values such as x = 0 and x = 2 give 1 and 3. Near x = 1 the outputs approach 2 rather than growing without bound.')],
pitfalls:['Calling every denominator zero a vertical asymptote before checking common factors.','Treating a graphing window as proof of behavior for all real inputs.'],engineering:'Graph features help reveal a model’s forbidden inputs and extreme behavior. A mathematical singularity may also signal that a simplified model is leaving its useful range.',reflection:'How can a formula approach a finite value at an input where it is undefined?',quiz:Q('For f(x) = 1/(x − 3), what is the vertical asymptote?',['y = 3','x = 0','x = 3','y = 0'],'c','The denominator approaches zero at x = 3 with no canceled factor; the function grows without bound in magnitude nearby.'),sources:[S('c','3-4-graphs-of-polynomial-functions','polynomial graphs'),S('c','3-7-rational-functions','rational functions')]},
{id:'radians-unit-circle',stage:'precalculus',order:43,title:'Radians and the unit circle',subtitle:'Measure a turn using the circle itself.',prerequisites:['circles-and-arcs','right-triangle-ratios'],
why:'Radians connect angle directly with arc length and become the standard angle measure in calculus. The unit circle extends trigonometry beyond acute triangles.',
explanation:[
'An angle in radians equals its intercepted arc length divided by the radius: θ = s/r. One radian sweeps an arc as long as the radius. Since a full circumference is 2πr, a full turn is 2π radians. Thus 180° = π radians. Convert degrees to radians by multiplying by π/180, and reverse that ratio for the opposite conversion.',
'On a circle of radius one centered at the origin, the point reached by angle θ has coordinates (cos θ, sin θ). Measure from the positive horizontal axis, with positive angles counterclockwise in the standard convention. This definition extends sine and cosine to all real angles, including turns beyond one revolution and negative rotations. Coterminal angles differ by whole multiples of 2π.',
'The quadrant determines signs: cosine follows the horizontal coordinate and sine follows the vertical coordinate. Reference angles connect familiar acute-triangle values to other quadrants. Do not memorize a circle full of disconnected numbers; use symmetry, the 45° triangle, and the 30°–60° triangle. The formula s = rθ requires radians, so using a degree number directly gives an incorrect scale.'
],worked:[W('Convert an angle and trace an arc','A radius of 3 m rotates through 120°.', ['Convert: 120 × π/180 = 2π/3 radians.','Arc length is rθ = 3 × 2π/3 = 2π m.','The angle lies in quadrant II, so cosine is negative and sine positive.'],'Angle 2π/3 radians; arc length 2π m.','120° is one third of a turn, and one third of circumference 6π m is 2π m.')],
pitfalls:['Using degrees directly in the radian arc-length formula.','Assigning signs from the reference angle while ignoring the actual quadrant.'],engineering:'Rotating mechanisms connect angular change to linear travel. The unit-circle view also prepares you to describe orientation and periodic signals.',reflection:'Why does the ratio arc length/radius remain the same for circles of different sizes at the same angle?',quiz:Q('Convert 225° to radians.',['3π/4','5π/4','4π/5','9π/4'],'b','225 × π/180 simplifies to 5π/4. It is π/4 radians, or 45°, beyond π.'),sources:[S('c','5-1-angles','radians'),S('c','5-2-unit-circle-sine-and-cosine-functions','the unit circle')]},
{id:'trigonometric-graphs',stage:'precalculus',order:44,title:'Sine waves, amplitude, and period',subtitle:'A repeated pattern becomes a function of time.',prerequisites:['radians-unit-circle','transform-compose-invert'],
why:'Periodic functions model idealized repeating behavior. Their parameters describe different features, so understanding them prevents guessing from the graph.',
explanation:[
'Sine and cosine repeat every 2π radians. Their basic values remain between −1 and 1. In y = A sin(ωt + φ) + C, the amplitude is |A|, the centerline is y = C, and for nonzero ω the period is 2π/|ω|. The phase φ shifts where the cycle begins. Read these as separate choices: how far, how fast, where centered, and where in the cycle.',
'When t is in seconds and the angle argument is in radians, ω represents angular frequency in radians per second. Ordinary frequency counts cycles per second and equals 1/T, where T is the period. For positive angular frequency, ω = 2πf; more generally, f = |ω|/(2π). Confusing frequency with angular frequency introduces a factor of 2π. A whole cycle returns to the same phase, not merely to the same vertical value once.',
'Start graphing with the centerline, maximum, minimum, and period. Then mark a few standard phase points. A real oscillation may have damping, multiple frequencies, noise, or changing amplitude; a single sinusoid is a deliberate simplification. Use the simple model to learn parameter meaning, then compare it with observations before treating it as a description of actual hardware.'
],worked:[W('Read an idealized displacement model','Let y(t) = 3 sin(πt/2) + 5, with y in cm and t in seconds.', ['Amplitude is 3 cm and centerline is 5 cm.','Angular frequency is π/2 rad/s, so period is 2π/(π/2) = 4 s.','At t = 1, sine receives π/2 and equals 1.','Therefore y(1) = 8 cm; the minimum is 5 − 3 = 2 cm.'],'Amplitude 3 cm; period 4 s; range 2 through 8 cm.','At t = 0 and t = 4, the model is at the centerline with the same phase.')],
pitfalls:['Calling the peak-to-peak range the amplitude; it equals twice the amplitude.','Confusing cycles per second with radians per second.'],engineering:'Ideal vibration and rotating-component projections often use sinusoidal models. Real dynamics require additional physics and validation.',reflection:'Which parameter would you change to double the period without changing the maximum or minimum?',quiz:Q('For y = 2 cos(3t), with t in seconds, what is the period?',['3 s','2π/3 s','6π s','2 s'],'b','The cosine argument must increase by 2π for one cycle. Thus 3T = 2π, giving T = 2π/3.'),sources:[S('c','6-1-graphs-of-the-sine-and-cosine-functions','sine and cosine graphs')]},
{id:'trig-identities-equations',stage:'precalculus',order:45,title:'Trigonometric identities and equations',subtitle:'Distinguish a universal relationship from selected solutions.',prerequisites:['trigonometric-graphs','rational-expressions'],
why:'Identities let you rewrite a relationship into a useful form. Trigonometric equations add the challenge of repeated solutions and domain restrictions.',
explanation:[
'The unit-circle coordinates satisfy x² + y² = 1. Substituting x = cos θ and y = sin θ gives sin²θ + cos²θ = 1. This is an identity: it holds for every real angle. The notation sin²θ means (sin θ)², not sin(θ²). Also tan θ = sin θ/cos θ wherever cosine is nonzero. Every identity involving division needs its own allowed domain.',
'An equation such as sin θ = 1/2 holds only for particular angles. On one full turn, the reference angle π/6 gives one solution in quadrant I and another in quadrant II at 5π/6. Additional full turns produce more solutions. Always read the requested interval: a problem on 0 ≤ θ < 2π asks for a different answer set from a problem over all real angles.',
'When simplifying or solving, do not divide by a trigonometric expression that might be zero without examining that case. Dividing sin θ cos θ = 0 by sin θ would lose the sine-zero solutions. The same algebraic caution you learned with ordinary variables still applies. Inverse trigonometric functions return selected principal values, so a calculator output is often only the starting point for finding all solutions.'
],worked:[W('Find all solutions in one turn','Solve sin θ = 1/2 for 0 ≤ θ < 2π.', ['The acute reference angle is π/6.','Sine is positive in quadrants I and II.','The second angle is π − π/6 = 5π/6.'],'θ = π/6 or 5π/6','Both have vertical unit-circle coordinate 1/2. Neither endpoint adds another solution in the stated interval.')],
pitfalls:['Treating an identity as though it holds only at a few tested angles.','Returning only the principal inverse-trig value when the interval contains another solution.'],engineering:'Trigonometric rearrangements support geometry and periodic models. Tracking all valid solutions matters when several orientations can produce the same measurement.',reflection:'Why does a sine measurement alone generally fail to identify a unique angle over a full turn?',quiz:Q('If sin θ = 3/5 and θ is acute, what is cos θ?',['3/5','4/5','−4/5','2/5'],'b','The identity gives cos²θ = 1 − 9/25 = 16/25. The acute-angle condition selects the positive root 4/5.'),sources:[S('c','5-2-unit-circle-sine-and-cosine-functions','unit-circle identities'),S('c','7-5-solving-trigonometric-equations','trigonometric equations')]},
{id:'vectors-and-components',stage:'precalculus',order:46,title:'Vectors, components, and projections',subtitle:'Preserve direction instead of adding only sizes.',prerequisites:['right-triangle-distance','radians-unit-circle'],
why:'Position changes and forces need direction as well as magnitude. Components make their combinations manageable while keeping the geometric meaning.',
explanation:[
'A vector has magnitude and direction. In a chosen plane, write components as (x, y). Two displacements combine by adding matching components, not by adding their magnitudes indiscriminately. A scalar multiplier changes a vector’s size and, if negative, reverses its direction. Coordinate axes and units must be specified before the numbers are physically interpretable.',
'The magnitude of (x, y) is √(x² + y²). For a vector of magnitude r at angle θ from the positive horizontal axis, the components are (r cos θ, r sin θ). Signs follow the direction. These formulas are a direct extension of unit-circle coordinates and similar triangles, so they connect earlier geometry rather than introducing an unrelated procedure.',
'The dot product of (a, b) and (c, d) is ac + bd. It also equals the product of their magnitudes times the cosine of their angle. Perpendicular nonzero vectors therefore have dot product zero. This gives an algebraic way to check alignment and introduces projections. Be careful when interpreting physical components in rotated coordinate frames; numbers can change with the frame while the underlying vector remains the same.'
],worked:[W('Combine two planar displacements','Add u = (3, 4) m and v = (−1, 2) m.', ['Add horizontal components: 3 + (−1) = 2.','Add vertical components: 4 + 2 = 6.','The resultant is (2, 6) m, with magnitude √(4 + 36) = √40 m.'],'Resultant (2, 6) m; magnitude 2√10 m, about 6.325 m.','Following both displacements reaches the same endpoint. Its straight-line distance is smaller than the sum of the two path lengths.')],
pitfalls:['Adding vector magnitudes without considering their directions.','Using a component formula with an angle measured from a different axis than assumed.'],engineering:'Robotics and aerospace calculations use coordinate frames for motion and force components. This planar introduction is the foundation for later three-dimensional work.',reflection:'How can two nonzero vectors add to zero?',quiz:Q('What is the magnitude of the vector (−8, 6)?',['2','10','14','100'],'b','Magnitude is √(64 + 36) = √100 = 10. Component signs affect direction, while squaring removes them from this length calculation.'),sources:[S('c','8-8-vectors','vectors')]},
{id:'exponential-log-equations',stage:'precalculus',order:47,title:'Solve exponential and logarithmic models',subtitle:'Turn an exponent into an unknown you can isolate.',prerequisites:['logarithms-introduction','transform-compose-invert'],
why:'Exponential models become more useful when you can solve for elapsed intervals or thresholds. Logarithms provide the algebraic inverse you need.',
explanation:[
'To solve an exponential equation, first isolate the exponential quantity. If both sides can be expressed with the same positive base other than one, compare their exponents. Otherwise take a logarithm of both sides, use the power rule, and isolate the unknown. For a bˣ = c, dividing by a gives bˣ = c/a; a real solution requires the right side to be positive when using this standard positive-base model.',
'For logarithmic equations, preserve the original positive-argument restrictions. Combining logarithms and exponentiating can produce algebraic candidates that violate those restrictions. Check them in the original expression. The domain is not optional bookkeeping: it determines whether the question had meaning before any transformation.',
'A decimal solution for time or cycle count also needs interpretation. A continuous model may permit a fractional time. A process observed only after whole cycles may require the first integer cycle beyond a threshold. Keep extra precision until that decision is made. In natural-exponential models A(t) = A₀e^(kt), k depends on the chosen time unit, so replacing hours with seconds changes its numerical value.'
],worked:[W('Find a decay threshold','A hypothetical quantity follows A(n) = 100(0.8)ⁿ. When does it reach 50?', ['Set 100(0.8)ⁿ = 50 and divide by 100.','Take logarithms: n ln(0.8) = ln(0.5).','Therefore n = ln(0.5)/ln(0.8) ≈ 3.106.','If only whole cycles count, the first cycle at or below 50 is cycle 4.'],'About 3.106 modeled cycles; first whole-cycle threshold at 4.','After 3 cycles the value is 51.2; after 4 it is 40.96, bracketing the threshold.')],
pitfalls:['Rounding a threshold down when the requirement is not yet met.','Keeping a logarithm-equation solution with a nonpositive original argument.'],engineering:'Threshold calculations are useful only as far as the fitted model remains valid. The algebra does not establish a real component’s lifetime or performance.',reflection:'Why can a fractional mathematical cycle and a whole-cycle operating decision both be correct answers to different questions?',quiz:Q('Solve 5 × 3ˣ = 135.',['2','3','4','27'],'b','Divide by 5 to get 3ˣ = 27 = 3³, so x = 3.'),sources:[S('c','4-6-exponential-and-logarithmic-equations','exponential and logarithmic equations')]},
{id:'bridge-to-calculus',stage:'precalculus',order:48,title:'From average change toward calculus',subtitle:'A preview of the question your algebra makes possible.',prerequisites:['functions-domain-range','polynomial-rational-graphs','vectors-and-components','exponential-log-equations'],
why:'Calculus builds on functions, algebra, and graphs to study change and accumulation. This preview explains the destination without treating a short lesson as a substitute for a course.',
explanation:[
'Average rate of change over an interval is [f(b) − f(a)]/(b − a), with b ≠ a. It is the slope of the line joining two points on the graph. For a linear function this rate is the same on every interval. For a curved function it can change with the chosen interval, which raises a new question: what rate should describe one instant?',
'A difference quotient uses a small nonzero change h: [f(x + h) − f(x)]/h. For f(x) = x², expanding and simplifying gives 2x + h when h ≠ 0. As h approaches zero, this expression approaches 2x. The simplification explains the behavior near zero without dividing by zero. Calculus develops this limiting idea carefully and calls the resulting instantaneous-rate function a derivative.',
'Another major calculus question asks how many small contributions accumulate into a total. If power varies with time, multiplying one power value by the entire duration may be inadequate; summing contributions over short intervals points toward integration. For now, your preparation is to manipulate expressions accurately, read graphs, track units, and distinguish an exact relation from an approximation. Course prerequisites and official placement determine when you enroll, not a single quiz here.'
],worked:[W('Compare a wide and a narrow interval','Use position f(t) = t² meters, with t in seconds, as a hypothetical model.', ['From t = 2 to 3, average rate is (9 − 4)/(3 − 2) = 5 m/s.','From t = 2 to 2.1, it is (4.41 − 4)/0.1 = 4.1 m/s.','The simplified quotient at t = 2 is 4 + h, approaching 4 as h approaches zero.'],'Average rates 5 and 4.1 m/s; the limiting rate at t = 2 is 4 m/s.','The two intervals produce different averages because the graph is curved, while both fit the same position formula.')],
pitfalls:['Substituting h = 0 directly into a quotient that divides by h.','Confusing an average rate over an interval with a value at one instant.'],engineering:'Mechanics, controls, and thermal models later use rates and accumulated quantities. Dependable algebra and trigonometry let you focus on those new ideas.',reflection:'Which part of the difference-quotient example required algebra, and which part introduced a new limiting question?',quiz:Q('For f(t) = t², what is the average rate of change from t = 1 to t = 4?',['3','4','5','15'],'c','The change in output is 16 − 1 = 15, over an input change of 4 − 1 = 3. The quotient is 5.'),sources:[S('c','1-3-rates-of-change-and-behavior-of-graphs','average rates of change')]}
];

export const lessons = [...arithmetic,...prealgebra,...algebra,...geometry,...algebra2,...precalculus];
export const curriculumSources = [...new Map(lessons.flatMap(lesson=>lesson.sources).map(source=>[source.url,source])).values()];
